/* Meraki by Saima — site behaviour.

   Product data enters through exactly one door: mapProduct(). Everything below
   the mapping layer renders the normalised shape and neither knows nor cares
   where a product came from — today /api/products, tomorrow the same endpoint
   backed by Supabase. Only the endpoint's data source changes. */

/* IMG-SRCSET:START — generated by tools/optimize-images.py, do not edit by hand */
var IMG_SRCSET = {
  'img/p1.webp': 'img/sm/p1.webp 560w, img/md/p1.webp 960w, img/p1.webp 1400w',
  'img/p2.webp': 'img/sm/p2.webp 560w, img/p2.webp 938w',
  'img/p3.webp': 'img/sm/p3.webp 560w, img/p3.webp 938w',
  'img/p4.webp': 'img/sm/p4.webp 560w, img/md/p4.webp 960w, img/p4.webp 1400w',
  'img/p5.webp': 'img/sm/p5.webp 560w, img/md/p5.webp 960w, img/p5.webp 1400w',
  'img/p6.webp': 'img/sm/p6.webp 560w, img/md/p6.webp 960w, img/p6.webp 1400w',
  'img/p7.webp': 'img/sm/p7.webp 560w, img/p7.webp 937w',
  'img/p8.webp': 'img/sm/p8.webp 560w, img/p8.webp 941w'
};
/* IMG-SRCSET:END */

/* ============================================================================
   MAPPING LAYER — the only place that understands the published contract
   ========================================================================== */

/* How each availability value presents to a customer.

   Availability is an inventory state and nothing more. It says whether a piece
   exists now or is cut to order; it cannot say how quickly Saima ships, so the
   website never derives a shipping time from it. A quantity is likewise never
   implied — the contract carries no stock counts. Which sizes exist is the only
   stock-shaped fact on the page, and that comes from `sizes`.

   A per-piece timing promise belongs to the app, in `fulfillment_note`. */
var AVAILABILITY = {
  ready_now:     { label: 'Ready now',                      dot: '#7A8B5A' },
  made_to_order: { label: 'Made to order',                  dot: '#A6802E' },
  both:          { label: 'Ready now · also made to order', dot: '#7A8B5A' }
};

var GARMENT_ROWS = [
  ['fabric', 'Fabric'],
  ['pieces', 'Pieces'],
  ['color',  'Color'],
  ['made',   'Made'],
  ['care',   'Care']
];

/* TEMPORARY, for launch. The catalogue carries sizing from several eras — some
   pieces list S/M, some list 38–46, some list nothing — so offering a size
   would mean offering a different vocabulary depending on which piece a
   customer happened to open. Until Ready Now and Made to Order have a sizing
   model of their own, size is settled in the follow-up conversation instead.
 *
 * Presentation only, and deliberately one switch. /api/products keeps
 * returning `sizes`, mapProduct keeps mapping them, and no stored data is
 * touched — so re-enabling this is this line, with nothing to migrate.
 *
 * Everything that reads it: the PDP size block, the Add to Inquiry button's
 * requirements, and the places the global size note is shown (a "sizes 38–46"
 * claim is confusing next to a page that offers no sizes). */
var SHOW_SIZE_SELECTION = false;

/* Never shown to a customer. The app keeps a custom option for its own use, but
   the storefront offers only sizes that actually exist — someone needing custom
   sizing says so in the inquiry note. */
var HIDDEN_SIZE_LABELS = ['other / custom', 'other', 'custom'];

function isPublicSize(label) {
  return !blank(label) && HIDDEN_SIZE_LABELS.indexOf(String(label).trim().toLowerCase()) === -1;
}

function blank(v) { return v === null || v === undefined || String(v).trim() === ''; }

function formatPrice(value, currency) {
  if (blank(value)) return '';
  if (typeof value !== 'number') return String(value);   /* already formatted */
  try {
    return new Intl.NumberFormat('en-US', {
      style: 'currency', currency: currency || 'USD',
      minimumFractionDigits: 0, maximumFractionDigits: value % 1 ? 2 : 0
    }).format(value);
  } catch (e) {
    return '$' + value;
  }
}

/* srcset has its own grammar: candidates are comma-separated and, inside a
   candidate, whitespace separates the URL from its descriptor. A URL carrying
   either character therefore cannot be written literally — it has to be
   percent-encoded, or the candidate list is misparsed.

   Only literal spaces and commas are touched, so a URL that already arrives
   percent-encoded is left exactly as it is rather than double-encoded. */
function srcsetSafeUrl(url) {
  return String(url).replace(/\s/g, '%20').replace(/,/g, '%2C');
}

/* The real pixel width of a rendition.

   The app keys its renditions by the LONGEST SIDE it targeted, not by the
   width of the file it produced. For a portrait photograph those are very
   different things: the "1400" rendition of a 937x1679 master is 781x1400, not
   1400 wide. Emitting `… 1400w` for a 781px file tells the browser it is
   getting nearly twice the detail it actually gets, and the browser then
   settles for a file far too small for the slot.

   A `w` descriptor must state the file's real width, so it is derived here
   from the master's aspect ratio. The clamp is what makes the derivation safe:
   the app never upscales, so no rendition can be wider than its master. If the
   longest-side reading is ever wrong for some image, this understates rather
   than overstates — and understating makes a browser pick a LARGER file, which
   costs bytes rather than sharpness. */
function variantWidth(key, masterW, masterH) {
  if (!(masterW > 0) || !(masterH > 0) || !(key > 0)) return null;
  var w = masterH > masterW ? Math.round(key * masterW / masterH) : key;
  return Math.max(1, Math.min(w, masterW));
}

/* "…/560.webp 313w, …/960.webp 536w, …/master.webp 937w".
 *
 * The master is included as a candidate on purpose. Once a srcset exists the
 * browser chooses only from it, so without the master the widest thing on
 * offer for Steel Grey would be 781px — narrower than a desktop gallery needs,
 * and guaranteed to look soft no matter how honest the other descriptors are.
 *
 * Descriptors can only be derived when the master's dimensions are known. If
 * they are not, no srcset is emitted at all and `src` — the master — serves.
 * Heavier, but never a lie about how much detail a file holds.
 *
 * Falls back to the generated IMG_SRCSET for the local editorial photography,
 * whose renditions really are keyed by width. */
function srcsetFrom(variants, src, masterW, masterH) {
  if (variants) {
    var keys = Object.keys(variants)
      .map(Number)
      .filter(function (k) { return k > 0 && !blank(variants[k]); })
      .sort(function (a, b) { return a - b; });

    if (keys.length) {
      var parts = [];
      var seenWidth = {};
      var seenUrl = {};
      var add = function (url, width) {
        /* Two candidates sharing a width is invalid srcset; after clamping to
           the master, small masters can collapse several keys onto one. And a
           rendition whose URL is simply the master — which happens when the
           app had nothing to downscale — must not be offered twice at two
           different widths, since only one of them can be true. */
        if (!width || blank(url) || seenWidth[width]) return;
        var safe = srcsetSafeUrl(url);
        if (seenUrl[safe]) return;
        seenWidth[width] = true;
        seenUrl[safe] = true;
        parts.push(safe + ' ' + width + 'w');
      };

      /* The master goes in first because its width is known outright rather
         than derived, so if a rendition turns out to be the master under
         another name the authoritative number is the one that survives. */
      add(src, masterW > 0 ? Math.round(masterW) : null);
      keys.forEach(function (k) { add(variants[k], variantWidth(k, masterW, masterH)); });

      /* Ascending by width: the browser does not care, but a human reading
         View Source does. */
      parts.sort(function (a, b) {
        return parseInt(a.split(' ').pop(), 10) - parseInt(b.split(' ').pop(), 10);
      });
      if (parts.length > 1) return parts.join(', ');
      return '';   /* nothing to choose between: let src serve */
    }
  }
  return IMG_SRCSET[src] || '';
}

/* Ordered by sort_order, with the primary photograph first. Every renderer
   treats images[0] as the hero, so hero selection is decided once, here. */
function mapImages(list, fallbackAlt) {
  var imgs = (list || [])
    .map(function (raw, i) {
      var img = (typeof raw === 'string') ? { src: raw } : (raw || {});
      return {
        src: img.src,
        alt: blank(img.alt) ? fallbackAlt : img.alt,
        role: img.role || null,
        width: img.width || null,
        height: img.height || null,
        isPrimary: img.is_primary === true,
        order: typeof img.sort_order === 'number' ? img.sort_order : i,
        srcset: srcsetFrom(img.variants, img.src, img.width, img.height)
      };
    })
    .filter(function (img) { return !blank(img.src); });

  imgs.sort(function (a, b) { return a.order - b.order; });

  for (var i = 0; i < imgs.length; i++) {
    if (imgs[i].isPrimary) { imgs.unshift(imgs.splice(i, 1)[0]); break; }
  }
  return imgs;
}

/* [label, value] pairs worth showing. A blank value is dropped rather than
   rendered as a labelled row with nothing beside it. */
function mapGarmentDetails(details) {
  var g = details || {};
  return GARMENT_ROWS
    .map(function (row) { return [row[1], g[row[0]]]; })
    .filter(function (row) { return !blank(row[1]); })
    .map(function (row) { return { key: null, label: row[0], values: [String(row[1]).trim()] }; });
}

/* The garment specification, as the endpoint decided it.
 *
 * /api/products already filtered the hidden and the blank, ordered the rows and
 * named them, so there is nothing left to decide here: what arrives is what
 * prints. The older `garment_details` shape is read only as a fallback, for the
 * minutes during a deploy when a browser can be holding this script while a
 * cached response still predates garment_specs. */
function mapGarmentSpecs(raw) {
  if (!Array.isArray(raw.garment_specs)) return mapGarmentDetails(raw.garment_details);

  return raw.garment_specs.map(function (row) {
    if (!row || blank(row.label) || !Array.isArray(row.values)) return null;
    var values = row.values
      .map(function (v) { return blank(v) ? '' : String(v).trim(); })
      .filter(Boolean);
    return values.length
      ? { key: row.key || null, label: String(row.label).trim(), values: values }
      : null;
  }).filter(Boolean);
}

/* The single door product data comes through. Everything downstream renders
   this shape and never touches the raw payload. */
function mapProduct(raw) {
  if (!raw || blank(raw.id)) return null;
  var avail = AVAILABILITY[raw.availability] || AVAILABILITY.made_to_order;
  var sizes = (raw.sizes || []).filter(isPublicSize);

  return {
    id: raw.id,
    slug: blank(raw.slug) ? raw.id : raw.slug,
    sku: raw.sku || null,
    name: raw.name || '',
    description: raw.description || '',
    price: formatPrice(raw.price, raw.currency),
    priceValue: raw.price,
    currency: raw.currency || 'USD',
    collections: raw.collection_names || [],
    availability: raw.availability || 'made_to_order',
    availabilityLabel: avail.label,
    dot: avail.dot,
    /* The piece's own note, exactly as the app stores it. Kept raw: what the
       page actually shows is resolved at render time by
       getEffectiveFulfillment(), because it may depend on a global setting
       that arrives separately. Nothing is ever written back. */
    fulfillmentNote: blank(raw.fulfillment_note) ? '' : String(raw.fulfillment_note).trim(),
    /* May legitimately be empty: the size selector then hides itself and the
       piece can still be added to an inquiry without one. */
    sizes: sizes,
    specs: mapGarmentSpecs(raw),
    images: mapImages(raw.images, raw.name || ''),
    /* The same mapping as the gallery — same variants, same truthful width
       descriptors, same master fallback — but a separate array, so nothing
       downstream can reach one set while meaning the other. */
    customerPhotos: mapImages(raw.customer_photos, raw.name || ''),
    publishedAt: raw.published_at || null
  };
}

function mapProducts(list) {
  return (list || []).map(mapProduct).filter(Boolean);
}

/* What the page should say about timing for one piece, right now.
 *
 * Two sources, and the piece's own note always wins:
 *
 *   ready_now      note → the note;  blank → nothing. The global made-to-order
 *                  lead time is a promise about making a piece, and a piece
 *                  that already exists is not being made. It must not apply.
 *   made_to_order  note → the note;  blank → the global lead time
 *   both           note → the note;  blank → the global lead time
 *
 * Blank on both sides means no line at all, never an empty one.
 *
 * Presentation only. The global value is read each time it is needed rather
 * than copied into the product, so changing the lead time in the app changes
 * every piece that relies on it, with nothing to migrate and nothing to go
 * stale. It is deliberately not part of the API contract.
 */
function getEffectiveFulfillment(product, settings) {
  if (!product) return '';
  if (!blank(product.fulfillmentNote)) return String(product.fulfillmentNote).trim();
  /* Only ready_now is excluded, so an unrecognised availability falls back the
     same way mapProduct's label does — made to order. */
  if (product.availability === 'ready_now') return '';
  var lead = settings && settings.made_to_order_lead_time;
  return blank(lead) ? '' : String(lead).trim();
}

/* Where the published catalogue and the operational settings are read from.
   Same origin, so no CORS, no credentials, no cookies. */
var PRODUCTS_ENDPOINT = '/api/products';
var SETTINGS_ENDPOINT = '/api/site-settings';

/* Everything Saima maintains in the app. Blank until the fetch resolves, and
   blank again if it fails — every consumer hides the line it cannot fill, so a
   settings outage costs a few footer lines rather than the whole storefront. */
function blankSettings() {
  return {
    featured_product_id: null, whatsapp: null, contact_email: null,
    instagram_url: null, location: null, made_to_order_lead_time: null,
    size_service_note: null, inquiry_response_note: null
  };
}
var SETTINGS = blankSettings();

/* The normalised catalogue every renderer reads. Empty until the fetch below
   resolves; it is mutated in place rather than reassigned so nothing can end up
   holding a reference to a stale array. */
var PRODUCTS = [];

var state = { filter:'all', slug:null, collection:null, edit:null, size:null, shot:0, bag:[], sent:false };

/* Is the catalogue usable yet? 'loading' | 'ready' | 'error'.

   Nothing is known until /api/products answers, so the page starts in
   'loading' and every view renders its waiting state from the outset. */
var catalogue = { status: 'loading', error: null };

/* Deliberately holds no product data of its own: the catalogue lives in
   PRODUCTS and response caching belongs to the CDN, not to the page. */
function setCatalogueState(status, error) {
  catalogue.status = status;
  catalogue.error = error || null;
  renderGrids();
  renderBag();
  route();   /* re-resolve wherever the visitor already is, without a refresh */
}

var $ = function (s) { return document.querySelector(s); };
var byId = function (id) { return document.getElementById(id); };

/* Identity is the id — a UUID once live. Never used in a URL. */
function findProduct(id) {
  return PRODUCTS.filter(function (p) { return p.id === id; })[0] || null;
}

/* Routing is the slug — human, shareable, stable across renames. Both return
   null when unknown, including while the catalogue is still empty; callers
   must handle that rather than assume a product came back. */
function findProductBySlug(slug) {
  return PRODUCTS.filter(function (p) { return p.slug === slug; })[0] || null;
}

/* Bags saved before ids and slugs were separated stored the slug under `id`.
   Resolving by id first and slug second keeps those inquiries intact without
   rewriting anything in storage. */
function findBagProduct(id) {
  return findProduct(id) || findProductBySlug(id);
}

/* Escape anything that ends up inside an HTML string below, so an apostrophe or
   an ampersand in a product name can never break the markup. */
function esc(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}

/* One image helper for every photograph on the site, local or remote. It takes
   a normalised image and emits srcset only when renditions actually exist, so
   a lone remote original still renders correctly from its src. */
function imgHTML(image, sizes, attrs) {
  if (!image || blank(image.src)) return '';
  return '<img src="' + esc(image.src) + '" alt="' + esc(image.alt) + '"' +
    (image.srcset ? ' srcset="' + esc(image.srcset) + '" sizes="' + esc(sizes) + '"' : '') +
    ' ' + (attrs || '') + '>';
}

/* ---------- cards ---------- */
var CARD_SIZES = '(max-width:640px) 92vw, (max-width:1100px) 44vw, 300px';

function cardHTML(p, small) {
  return '<a class="card" href="#/product/' + esc(p.slug) + '">' +
    '<div class="shot">' + imgHTML(p.images[0], CARD_SIZES, 'loading="lazy" decoding="async"') + '</div>' +
    '<div class="meta"><p class="name">' + esc(p.name) + '</p><p class="price">' + esc(p.price) + '</p>' +
    (small ? '' : '<p class="status"><span class="dot" style="background:' + esc(p.dot) + '"></span>' + esc(p.availabilityLabel) + '</p>') +
    '</div></a>';
}

/* 'both' belongs in both lists, so the filters test what a piece can be rather
   than sorting it into one bucket. */
/* ---------- collections ---------- */

/* A URL-safe form of a collection's name. Deterministic and one-way: the name
   is what gets displayed, the slug is only ever an address.

   Accents are folded rather than dropped, so "Été" addresses as "ete" instead
   of collapsing to nothing. Apostrophes close up — "Saima's Edit" is
   "saimas-edit", not "saima-s-edit" — and every other run of punctuation
   becomes a single hyphen. A name made entirely of punctuation yields '', and
   the caller treats that as unaddressable rather than routing to nowhere. */
function collectionSlug(name) {
  var s = String(name == null ? '' : name).trim().toLowerCase();
  if (s.normalize) s = s.normalize('NFKD').replace(/[\u0300-\u036f]/g, '');
  return s.replace(/['‘’ʼ]/g, '')
          .replace(/[^a-z0-9]+/g, '-')
          .replace(/^-+|-+$/g, '');
}

/* Every collection the public catalogue actually contains.

   PRODUCTS holds exactly what /api/products returned, and that endpoint admits
   a row only when it is published and not archived — the guard lives in the
   query and again in the handler. So "a collection with at least one visible
   product" needs no second definition here: it is whatever these products say
   they belong to. A collection whose every piece is unpublished or archived
   never reaches the browser, and so never reaches this list.

   Deduplicated by slug rather than by name, so two spellings that address the
   same URL cannot both claim it. First spelling seen wins the display name.

   Ordering is alphabetical by display name, case-insensitively and
   locale-aware. Nothing in the public payload expresses merchandising
   priority, and inventing one from creation dates or product counts would be
   guessing at intent. Alphabetical is the honest default; an app-side phase
   can supply a real order later. */
function publicCollections() {
  var seen = {};
  var out = [];
  PRODUCTS.forEach(function (p) {
    (p.collections || []).forEach(function (raw) {
      var name = String(raw == null ? '' : raw).trim();
      if (!name) return;
      var slug = collectionSlug(name);
      if (!slug || seen[slug]) return;
      seen[slug] = true;
      out.push({ name: name, slug: slug });
    });
  });
  return out.sort(function (a, b) {
    return a.name.localeCompare(b.name, 'en', { sensitivity: 'base' });
  });
}

function findCollectionBySlug(slug) {
  if (blank(slug)) return null;
  var want = collectionSlug(slug);
  return publicCollections().filter(function (c) { return c.slug === want; })[0] || null;
}

/* Membership is compared by slug so a route resolves the same way the menu
   built it — no second normalisation rule to drift out of step. */
function inCollection(p, collection) {
  if (!collection) return true;
  return (p.collections || []).some(function (n) {
    return collectionSlug(n) === collection.slug;
  });
}

function matchesFilter(p, filter) {
  if (filter === 'all') return true;
  if (filter === 'ready') return p.availability === 'ready_now' || p.availability === 'both';
  return p.availability === 'made_to_order' || p.availability === 'both';
}

/* Which piece the home hero shows is Saima's choice, made in the app and read
   from Website Settings as a product id. It is resolved against the published
   catalogue, which is already filtered to published and unarchived — so a
   featured piece that is retired, archived or unpublished simply stops
   resolving, and the hero goes back to being a photograph with no caption.
   There is deliberately no fallback piece: naming a garment Saima did not
   choose is worse than naming none. */
function featuredProduct() {
  return blank(SETTINGS.featured_product_id) ? null : findProduct(SETTINGS.featured_product_id);
}

/* The editorial photograph exactly as index.html shipped it, captured before
   anything can overwrite it so the hero can always be put back. Without this
   the swap is one-way: once a product photograph is in place, a later render
   that has no product to show leaves the wrong garment on screen. */
var HERO_EDITORIAL = null;

/* Null while the homepage hero is the Roselle film. Everything downstream
   already guards on it, so the featured-product photograph swap simply has
   nothing to swap rather than throwing. */
function heroImg() { return $('.hero-img img'); }

function captureHeroEditorial() {
  var img = heroImg();
  if (!img || HERO_EDITORIAL) return;
  HERO_EDITORIAL = {
    src: img.getAttribute('src'), srcset: img.getAttribute('srcset'),
    sizes: img.getAttribute('sizes'), alt: img.getAttribute('alt')
  };
}

function setHeroImage(shot) {
  var img = heroImg();
  if (!img || !shot || blank(shot.src)) return;
  if (img.getAttribute('src') === shot.src) return;   /* already right; don't refetch */
  img.src = shot.src;
  img.alt = shot.alt || '';
  if (shot.srcset) { img.srcset = shot.srcset; img.sizes = shot.sizes || '(max-width:940px) 100vw, 53vw'; }
  else { img.removeAttribute('srcset'); img.removeAttribute('sizes'); }
}

/* The caption and the photograph move together or not at all.
 *
 * Three things could otherwise disagree — the caption, the photograph and the
 * alt text — and any two of them naming different garments is worse than
 * showing no caption. So there are exactly two safe states:
 *
 *   a featured piece that resolves AND has a photograph → its caption, its
 *   photograph, its alt
 *
 *   anything else → the editorial photograph with its own alt, no caption
 *
 * A featured piece with no usable image is not a partial success; it falls
 * back completely. */
function renderHero() {
  var tag = byId('hero-tag');
  if (!tag) return;
  captureHeroEditorial();

  var p = featuredProduct();
  var shot = (p && p.images.length && !blank(p.images[0].src)) ? p.images[0] : null;
  var safe = !!(p && shot);

  tag.classList.toggle('hidden', !safe);

  if (!safe) {
    byId('hero-name').textContent = '';
    byId('hero-status').textContent = '';
    setHeroImage(HERO_EDITORIAL);
    return;
  }

  byId('hero-name').textContent = p.name;
  byId('hero-status').textContent = p.availabilityLabel;
  setHeroImage(shot);
}

/* Whether the global size note may be shown to a customer at all. It reads
   "sizes 38–46 and custom" — a promise the storefront cannot currently let
   anyone act on, so while size selection is hidden the note is hidden with it
   everywhere rather than reworded into something new. The setting itself is
   untouched and comes straight back when sizing returns. */
function sizeServiceNote() {
  return SHOW_SIZE_SELECTION ? SETTINGS.size_service_note : null;
}

/* "12 pieces · sizes 38–46 and custom". The size clause is Saima's, from
   Website Settings — the range the atelier actually offers changes, and a
   number written into the page here would go on claiming the old one. No note
   set means no clause. */
function collectionCount(n) {
  var note = sizeServiceNote();
  return n + (n === 1 ? ' piece' : ' pieces') + (blank(note) ? '' : ' · ' + note);
}

/* One item per collection, plus the way back to everything. The markup is
   identical in both menus; only where it hangs differs. */
function collectionNavHTML() {
  var items = publicCollections().map(function (c) {
    return '<li><a class="navmenu-item" href="#/collection/' + esc(c.slug) + '"'
      + ' data-collection="' + esc(c.slug) + '">' + esc(c.name) + '</a></li>';
  });
  items.push('<li class="navmenu-all"><a class="navmenu-item" href="#/collection">View All</a></li>');
  return items.join('');
}

/* An edit is offered only when a visitor could actually use it: the app has
   published it (the endpoint already filtered on show_on_website), and at least
   one of its pieces is still live. An edit whose garments have all been retired
   is a heading over an empty page, so it is not put in front of anyone. */
function publicEdits() {
  return (CURATED_EDITS || []).filter(function (e) {
    if (!e || blank(e.slug) || blank(e.title)) return false;
    return (e.product_ids || []).some(function (id) { return !!findProductById(id); });
  });
}

/* Every public edit is named outright in the header, at the same level as
   Collections — the same type, the same weight, the same spacing. An edit is a
   destination, not a category, and putting a handful of them behind a word that
   says nothing about any of them ("Edits") asks the visitor to open a menu to
   learn what could simply have been shown.

   Order is whatever the payload supplies; nothing here sorts it, because a
   sort would be this file inventing a merchandising priority that belongs to
   the app. */
function editNavHTML(edits) {
  return edits.map(function (e) {
    var slug = String(e.slug).trim();
    return '<a class="navlink navlink-edit" href="#/edit/' + esc(slug) + '"'
      + ' data-edit="' + esc(slug) + '" title="' + esc(e.title) + '">'
      + esc(e.title) + '</a>';
  }).join('');
}

function renderEditsNav() {
  var html = editNavHTML(publicEdits());
  ['edits-nav', 'mob-edits-nav'].forEach(function (id) {
    var el = byId(id);
    if (el) el.innerHTML = html;
  });
}

function renderCollectionNav() {
  var html = collectionNavHTML();
  var desktop = byId('collections-list');
  var mobile = byId('mob-collections-list');
  if (desktop) desktop.innerHTML = html;
  /* The mobile panel is a plain list too, so one renderer serves both. */
  if (mobile) mobile.innerHTML = '<ul class="navmenu-list-inner">' + html + '</ul>';
}

/* ===========================================================================
 * HOMEPAGE MERCHANDISING
 * ===========================================================================
 *
 * Everything here is decided in the app and arrives, already validated and with
 * its CTAs already resolved to real addresses, from /api/site-settings. The
 * browser never sees a collection id, an edit id, or an href the app wrote.
 *
 * The rule that outranks every other rule in this file: a homepage that has
 * never been merchandised looks exactly as it did before any of this existed.
 * HOMEPAGE stays null until the endpoint says otherwise, and a block that is
 * absent from the configuration stays absent rather than being conjured from
 * its defaults — so configuring a campaign alone changes the hero and nothing
 * else.
 */
var HOMEPAGE = null;
var CURATED_EDITS = [];
/* 'loading' until /api/site-settings has answered one way or the other. HOMEPAGE
   is null both before the answer and when the answer is "nothing configured",
   so it cannot be used to tell those two apart — and the difference decides
   whether several megabytes of film are worth fetching. */
var homepageState = 'loading';

function homepageBlock(name) {
  return HOMEPAGE && HOMEPAGE[name] ? HOMEPAGE[name] : null;
}

function findEditBySlug(slug) {
  if (blank(slug)) return null;
  var want = String(slug).trim().toLowerCase();
  /* The stored slug, compared as stored. It is the operator's to edit and
     survives a title rename, so deriving one from the title here would send
     people to a page that no longer answers. */
  return CURATED_EDITS.filter(function (e) {
    return String(e.slug || '').trim().toLowerCase() === want;
  })[0] || null;
}

function findProductById(id) {
  if (blank(id)) return null;
  return PRODUCTS.filter(function (p) { return p.id === id; })[0] || null;
}

/* Newest first. website_published_at is when Saima put it on the site, which is
   what "new" means to a visitor; created_at is the fallback for a piece that
   predates the column. */
function newestFirst(products) {
  return products.slice().sort(function (a, b) {
    var av = a.publishedAt || a.createdAt || '';
    var bv = b.publishedAt || b.createdAt || '';
    return av < bv ? 1 : av > bv ? -1 : 0;
  });
}

/* The pieces a featured edit resolves to, in the order they should appear.
   Nothing here pads: if four of six chosen pieces are still published, four is
   the honest answer, and the saved configuration is never rewritten to match. */
function featuredEditProducts(cfg) {
  if (!cfg || cfg.show !== true) return [];
  var out = [];

  if (cfg.source_type === 'collection') {
    var collection = findCollectionBySlug(cfg.source_collection_slug);
    /* collection_names already carries only publicly visible memberships of
       publicly visible collections, so honouring 028's two switches here is
       simply a matter of using it. */
    out = collection
      ? newestFirst(PRODUCTS.filter(function (p) { return inCollection(p, collection); }))
      : [];
  } else if (cfg.source_type === 'products') {
    out = (cfg.product_ids || []).map(findProductById).filter(Boolean);
  } else {
    out = newestFirst(PRODUCTS);
  }

  return out.slice(0, cfg.count > 0 ? cfg.count : 0);
}

/* What a configured featured edit is called.
 *
 * The heading the app was given, first. Failing that, the edit its link leads
 * to — a block that says "shop these" and points at Eid Picks is called Eid
 * Picks, and that name is already in the payload.
 *
 * Failing both, a generic label. Specifically NOT the words sitting in the
 * markup: those are the unconfigured homepage's editorial copy, they name a
 * real collection, and letting them stand over an arbitrary configured
 * selection tells the visitor the pieces are something they are not. An
 * untitled edit is generic; it is not that collection. */
function featuredEditTitle(cfg) {
  if (!blank(cfg.heading)) return String(cfg.heading).trim();
  if (cfg.cta && !blank(cfg.cta.href)) {
    var m = /^#\/edit\/(.+)$/.exec(String(cfg.cta.href).trim());
    var linked = m ? findEditBySlug(m[1]) : null;
    if (linked && !blank(linked.title)) return String(linked.title).trim();
  }
  return 'Featured Collection';
}

/* The homepage's movable sections, in the order the app asked for. The DOM
   carries the website's own order; this rearranges it rather than re-rendering,
   so nothing is built twice and a section that is not mentioned keeps working.
   Sections that render nothing are already hidden by their own renderers, so a
   disabled one leaves no gap here either. */
var SECTION_NODES = { campaign: '.hero', featured_edit: '#featured', new_arrivals: '#new-arrivals' };

function applySectionOrder() {
  var order = HOMEPAGE && HOMEPAGE.section_order;
  if (!order || !order.length) return;
  var home = byId('view-home');
  if (!home) return;
  /* Anchored on the first section rather than the top of the view: everything
     below these three — the story, the made-to-order panel, the closing
     invitation — is the website's and does not move. */
  var nodes = order.map(function (k) { return $(SECTION_NODES[k]); }).filter(Boolean);
  if (!nodes.length) return;
  var anchor = nodes[0];
  home.insertBefore(anchor, home.firstChild);
  nodes.slice(1).forEach(function (n) {
    anchor.parentNode.insertBefore(n, anchor.nextSibling);
    anchor = n;
  });
}

/* ---------------------------------------------------------------------------
 * Horizontal rails.
 *
 * One small controller for both, because they differ only in what they hold
 * and whether they move on their own. Scroll-snap does the work — the track is
 * a real scroller, so a trackpad, a touch drag, a keyboard and the arrows all
 * drive the same thing and none of it is a bespoke drag implementation.
 *
 * "A page" is however many cards are actually visible, measured rather than
 * assumed, so the same code gives two on a phone and four on a wide screen
 * without a breakpoint table to keep in step with the CSS.
 * ------------------------------------------------------------------------- */
function railPage(track) {
  var card = track.firstElementChild;
  if (!card) return { size: 1, step: track.clientWidth };
  var w = card.getBoundingClientRect().width;
  var gap = parseFloat(getComputedStyle(track).columnGap || getComputedStyle(track).gap) || 0;
  var per = Math.max(1, Math.round((track.clientWidth + gap) / (w + gap)));
  return { size: per, step: per * (w + gap) };
}

function railSyncArrows(rail) {
  var track = byId(rail.track);
  var prev = byId(rail.prev);
  var next = byId(rail.next);
  if (!track || !prev || !next) return;
  var over = track.scrollWidth - track.clientWidth;
  /* Nothing to scroll means no controls at all, rather than two dead ones. */
  var scrollable = over > 4;
  prev.classList.toggle('hidden', !scrollable);
  next.classList.toggle('hidden', !scrollable);
  if (!scrollable) return;
  prev.disabled = track.scrollLeft <= 2;
  next.disabled = track.scrollLeft >= over - 2;
}

function railMove(rail, dir, manual) {
  var track = byId(rail.track);
  if (!track) return;
  var page = railPage(track);
  var over = track.scrollWidth - track.clientWidth;
  var to = track.scrollLeft + dir * page.step;
  /* Autoplay wraps so the rail keeps offering something; a manual move stops
     at the end, because someone pressing "next" at the end meant the end. */
  if (!manual && to > over - 2) to = 0;
  to = Math.max(0, Math.min(to, over));

  /* Automatic movement never slides an unresolved photograph into view. A
     person asking to move is different: they are told nothing and made to
     wait for a picture, so a manual move happens at once and the placeholder
     carries the gap. */
  if (!manual && !cardsReady(cardsAt(track, to))) {
    preloadCards(cardsAt(track, to));
    rail.waiting = true;
    return;
  }
  rail.waiting = false;

  track.scrollTo({ left: to, behavior: reducedMotion() ? 'auto' : 'smooth' });
  /* One group ahead of wherever this move lands. */
  preloadCards(cardsAt(track, Math.min(to + page.step, over)));
  if (manual) railDelay(rail);
}

/* Autoplay never resumes instantly after a touch. The rail should never feel
   like it is arguing with the person using it. */
function railDelay(rail) {
  if (!rail.interval) return;
  if (rail.timer) { clearInterval(rail.timer); rail.timer = null; }
  if (rail.resume) clearTimeout(rail.resume);
  rail.resume = setTimeout(function () { railPlay(rail); }, rail.interval * 2);
}

function railPlay(rail) {
  if (!rail.interval || reducedMotion()) return;
  var track = byId(rail.track);
  if (!track || track.scrollWidth - track.clientWidth <= 4) return;
  /* Reaching the rail is the moment the next group becomes worth fetching. */
  preloadCards(cardsAt(track, Math.min(track.scrollLeft + railPage(track).step,
    track.scrollWidth - track.clientWidth)));
  if (rail.timer) clearInterval(rail.timer);
  rail.timer = setInterval(function () {
    if (document.hidden) return;
    railMove(rail, 1, false);
  }, rail.interval);
}

function railStop(rail) {
  if (rail.timer) { clearInterval(rail.timer); rail.timer = null; }
  if (rail.resume) { clearTimeout(rail.resume); rail.resume = null; }
}

/* Bound once. Everything after this is the browser's own scrolling. */
function bindRail(rail) {
  if (rail.bound) return;
  var track = byId(rail.track);
  if (!track) return;
  rail.bound = true;

  var prev = byId(rail.prev), next = byId(rail.next);
  if (prev) prev.addEventListener('click', function () { railMove(rail, -1, true); });
  if (next) next.addEventListener('click', function () { railMove(rail, 1, true); });

  track.addEventListener('scroll', function () { railSyncArrows(rail); }, { passive: true });
  /* Any hand on the rail — a drag, a trackpad, a wheel — postpones autoplay. */
  ['touchstart', 'pointerdown', 'wheel'].forEach(function (ev) {
    track.addEventListener(ev, function () { railDelay(rail); }, { passive: true });
  });

  if (rail.interval) {
    /* The timer starts when the section is actually reached, not when the page
       loads — a rail that has already shuffled itself twice before anyone
       scrolls to it has wasted the pieces it was showing. */
    if (window.IntersectionObserver) {
      rail.io = new IntersectionObserver(function (entries) {
        entries.forEach(function (entry) {
          if (entry.isIntersecting) railPlay(rail);
          else railStop(rail);
        });
      }, { threshold: 0.4 });
      rail.io.observe(track);
    } else {
      railPlay(rail);   /* no observer: better moving than never moving */
    }
  }

  window.addEventListener('resize', function () { railSyncArrows(rail); });
}

var ARRIVALS_RAIL = { track: 'arrivals-track', prev: 'arrivals-prev', next: 'arrivals-next',
  interval: 2000, timer: null, resume: null, bound: false, io: null, waiting: false };
var SEEN_RAIL = { track: 'seen-track', prev: 'seen-prev', next: 'seen-next',
  /* Deliberately no interval. Customer photographs are looked at, not shown. */
  interval: 0, timer: null, resume: null, bound: false, io: null, waiting: false };

/* A compact card for the rails. Same product contract and the same routing as
   the grid card — only the frame is smaller, because a homepage rail should
   offer many pieces without the page becoming very tall.

   `eager` is for the cards that will already be on screen when the rail is
   reached. Lazy-loading those was the whole reason the rail sat blank for a
   couple of seconds: the browser waits for layout before it will even begin
   fetching a lazy image, so the first two cards started late and finished
   later. Everything past the first group stays lazy — a rail of twenty pieces
   must not become twenty downloads. */
var RAIL_SIZES = '(max-width:640px) 44vw, (max-width:1100px) 30vw, 260px';

/* The most cards that can be on screen at once, across every breakpoint. Used
   only to decide how many to load eagerly before layout exists to measure. */
var RAIL_MAX_VISIBLE = 4;

function railCardHTML(p, i) {
  var eager = i < RAIL_MAX_VISIBLE;
  var attrs = eager
    ? 'loading="eager" fetchpriority="high" decoding="async"'
    : 'loading="lazy" decoding="async"';
  return '<a class="rail-card" href="#/product/' + esc(p.slug) + '">'
    + '<div class="shot is-waiting">' + imgHTML(p.images[0], RAIL_SIZES, attrs) + '</div>'
    + '<div class="meta"><p class="name">' + esc(p.name) + '</p>'
    + '<p class="price">' + esc(p.price) + '</p></div></a>';
}

/* ---------------------------------------------------------------------------
 * Image readiness.
 *
 * A photograph is "resolved" once the browser has finished with it either way
 * — loaded, or failed for good. Both are terminal: a picture that will never
 * arrive must not hold the rail still forever, so an error resolves exactly as
 * a success does and only the placeholder stays behind.
 * ------------------------------------------------------------------------- */
function markResolved(img, ok) {
  var shot = img.parentNode;
  if (!shot) return;
  img.dataset.resolved = '1';
  shot.classList.remove('is-waiting');
  /* Loaded: the garment crossfades up over the placeholder. Failed: the image
     is taken out of the picture entirely rather than left to draw the
     browser's broken-file icon, and the feather stays where it was. */
  shot.classList.add(ok ? 'is-loaded' : 'is-failed');

  /* A rail that held still for this photograph should go as soon as it
     arrives, rather than sitting out the rest of a tick it already missed.
     railPlay restarts the interval, so the move it was owed does not land on
     top of the tick that was already due and advance two groups at once. */
  if (ARRIVALS_RAIL.waiting) {
    ARRIVALS_RAIL.waiting = false;
    railMove(ARRIVALS_RAIL, 1, false);
    railPlay(ARRIVALS_RAIL);
  }
}

function watchRailImages(track) {
  if (!track) return;
  Array.prototype.forEach.call(track.querySelectorAll('img'), function (img) {
    if (img.dataset.watched) return;
    img.dataset.watched = '1';
    /* Already in the cache: complete before a listener could ever fire. */
    if (img.complete) {
      markResolved(img, img.naturalWidth > 0);
      return;
    }
    img.addEventListener('load', function () { markResolved(img, true); });
    img.addEventListener('error', function () { markResolved(img, false); });
  });
}

/* The cards whose photographs would be on screen at a given scroll position. */
function cardsAt(track, left) {
  var out = [];
  var w = track.clientWidth;
  Array.prototype.forEach.call(track.children, function (card) {
    var x = card.offsetLeft - track.offsetLeft;
    if (x + card.offsetWidth > left + 2 && x < left + w - 2) out.push(card);
  });
  return out;
}

function cardsReady(cards) {
  return cards.every(function (card) {
    var img = card.querySelector('img');
    return !img || img.dataset.resolved === '1';
  });
}

/* Start fetching a group before it is needed, so the two-second tick usually
   finds it already there. One group ahead only — never the whole rail. */
function preloadCards(cards) {
  cards.forEach(function (card) {
    var img = card.querySelector('img');
    if (!img || img.dataset.resolved === '1') return;
    if (img.loading === 'lazy') img.loading = 'eager';
  });
}


/* One photograph for each piece someone has sent one in for.
 *
 * The homepage is a way into the catalogue, so a piece earns one tile however
 * many photographs it has — four tiles of the same suit would crowd out three
 * other pieces. The one chosen is the first in the order the PDP already uses,
 * which mapImages settled: sort_order ascending, with a primary photograph
 * hoisted in front. So reordering in the app, or deleting the first, changes
 * what the homepage shows with nothing here to update.
 *
 * PRODUCTS holds only published, unarchived pieces, so eligibility is the
 * catalogue's own and there is no second rule. The URL check is a secondary
 * safety net for the same file arriving under two pieces — product-level
 * selection has already done the real work. */
function customerLooks() {
  var out = [];
  var seen = {};
  newestFirst(PRODUCTS).forEach(function (p) {
    var first = (p.customerPhotos || [])[0];
    if (!first || blank(first.src) || seen[first.src]) return;
    seen[first.src] = true;
    out.push({ product: p, img: first });
  });
  return out;
}

var LOOK_SIZES = '(max-width:640px) 44vw, (max-width:1100px) 30vw, 240px';

function renderCustomerLooks() {
  var section = byId('home-seen');
  var track = byId('seen-track');
  if (!section || !track) return;

  var looks = customerLooks();
  section.classList.toggle('hidden', looks.length === 0);
  if (!looks.length) { track.innerHTML = ''; railStop(SEEN_RAIL); return; }

  track.innerHTML = looks.map(function (l, i) {
    var eager = i < RAIL_MAX_VISIBLE;
    return '<a class="look" href="#/product/' + esc(l.product.slug) + '"'
      + ' aria-label="' + esc(l.product.name) + ' — seen on a customer">'
      + '<span class="shot is-waiting">'
      + imgHTML(l.img, LOOK_SIZES, eager
        ? 'loading="eager" decoding="async"' : 'loading="lazy" decoding="async"')
      + '</span></a>';
  }).join('');

  watchRailImages(track);
  bindRail(SEEN_RAIL);
  railSyncArrows(SEEN_RAIL);
}

function renderHomeSections() {
  var edit = homepageBlock('featured_edit');
  var arrivalsCfg = homepageBlock('new_arrivals');

  /* An absent block is not a decision to hide anything: the section keeps doing
     what it did before the app knew about it. */
  var featured = edit ? featuredEditProducts(edit) : PRODUCTS.slice(0, 4);
  var section = byId('featured');

  section.classList.toggle('hidden', featured.length === 0);
  byId('featured-grid').innerHTML = featured.map(function (p) { return cardHTML(p); }).join('');

  if (edit) byId('featured-title').textContent = featuredEditTitle(edit);
  var sub = byId('featured-sub');
  var subtitle = edit ? edit.subtitle : null;
  sub.textContent = blank(subtitle) ? '' : subtitle;
  sub.classList.toggle('hidden', blank(subtitle));

  /* Already resolved server-side, or absent. There is nothing to decide here
     and deliberately no way for a heading to imply a destination. */
  var cta = byId('featured-cta');
  var resolved = edit ? edit.cta : { label: 'All pieces', href: '#/collection' };
  cta.classList.toggle('hidden', !resolved);
  if (resolved) { cta.textContent = resolved.label; cta.setAttribute('href', resolved.href); }

  /* The See More control belongs to the unconfigured homepage. A configured
     edit says where it goes with its own CTA. */
  byId('featured-more').classList.toggle('hidden', !!edit);

  /* The pieces New Arrivals shows.
   *
   * When the app has expressed a selection, that selection is the answer and
   * the storefront only resolves the ids — an id that no longer names a
   * published piece simply is not found, so the rail shortens rather than
   * showing a gap, and no count caps it. The seeding, the auto-adding and the
   * sticky removals all stayed in the app, where there is one implementation
   * of them.
   *
   * With no selection, the behaviour from before the app knew about this is
   * kept exactly: the newest pieces, minus whatever the edit above already
   * shows, capped by the configured count. */
  var arrivals = [];
  if (arrivalsCfg && arrivalsCfg.show !== false) {
    if (arrivalsCfg.product_ids) {
      arrivals = arrivalsCfg.product_ids.map(findProductById).filter(Boolean);
    } else {
      var shown = {};
      if (arrivalsCfg.exclude_featured !== false) {
        featured.forEach(function (p) { shown[p.id] = true; });
      }
      arrivals = newestFirst(PRODUCTS)
        .filter(function (p) { return !shown[p.id]; })
        .slice(0, arrivalsCfg.count > 0 ? arrivalsCfg.count : 0);
    }
  }
  byId('new-arrivals').classList.toggle('hidden', arrivals.length === 0);
  byId('arrivals-track').innerHTML = arrivals.map(railCardHTML).join('');
  if (arrivalsCfg) byId('arrivals-title').textContent = arrivalsCfg.heading || 'New Arrivals';

  if (arrivals.length) {
    watchRailImages(byId('arrivals-track'));
    bindRail(ARRIVALS_RAIL);
    railSyncArrows(ARRIVALS_RAIL);
  } else {
    railStop(ARRIVALS_RAIL);
  }

  renderCustomerLooks();
}

/* The default hero's film, brought to life.
 *
 * Its address sits in data-src until here, because a <source> in the markup is
 * fetched by the browser's preload scanner during parsing — before any script
 * runs. On a visit where a campaign is live that would download a film nobody
 * sees. This is the moment the site knows the default hero is the one being
 * shown, so this is the moment the film gets a source.
 *
 * Runs once. Calling it again on a later render must not restart the download
 * or interrupt playback. */
function activateDefaultHero() {
  var video = byId('hero-video');
  if (!video || video.dataset.activated) return;
  var url = video.dataset.src;
  if (!url) return;

  video.dataset.activated = '1';
  if (video.dataset.poster) video.setAttribute('poster', video.dataset.poster);
  video.setAttribute('preload', 'auto');
  video.setAttribute('autoplay', '');

  var source = document.createElement('source');
  source.setAttribute('type', 'video/mp4');
  source.setAttribute('src', url);
  video.insertBefore(source, video.firstChild);
  /* Without this the element keeps the empty network state it was parsed with
     and never looks at the source just added. */
  video.load();
  setupHeroFilm();
}

/* The campaign hero. Rendered only when the app has actually said something —
   otherwise the film and copy already in the markup are left entirely alone,
   which is what keeps migration 029 from changing the site by existing. */
var HERO_BTNROW = null;
/* The unconfigured hero's own words and media, kept so that anything a
   campaign does not specify can be put back rather than inherited. Without
   this a second slide with no heading would wear the first slide's, and a
   campaign with no media would sit under the previous campaign's film. */
var HERO_DEFAULTS = null;

function captureHeroDefaults() {
  if (HERO_DEFAULTS) return;
  var heading = byId('hero-heading');
  var lede = $('.hero-copy .lede');
  var film = $('.hero-film');
  HERO_DEFAULTS = {
    heading: heading ? heading.innerHTML : '',
    lede: lede ? lede.textContent : '',
    film: film ? film.innerHTML : ''
  };
}

/* ---------------------------------------------------------------------------
 * The hero carousel.
 *
 * One campaign is not a carousel and is deliberately not rendered as one: no
 * dots, no timer, no listeners — exactly the single hero that existed before,
 * so the common case carries none of this weight.
 *
 * Motion is the quietest thing that still reads as a change: a crossfade at an
 * editorial pace, and none at all for anyone who has asked for reduced motion.
 * ------------------------------------------------------------------------- */
var HERO_INTERVAL = 5000;
var hero = { slides: [], index: 0, timer: null, bound: false };

function reducedMotion() {
  return !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
}

/* Every campaign the app published, newest contract first. The singular field
   is read only when the array is absent, which happens while a browser is
   still holding a response cached from before campaigns existed. */
function activeCampaigns() {
  var many = HOMEPAGE && HOMEPAGE.campaigns;
  if (many && many.length) return many;
  var one = homepageBlock('campaign');
  return one ? [one] : [];
}

function heroStopTimer() {
  if (hero.timer) { clearInterval(hero.timer); hero.timer = null; }
}

/* Restarted rather than resumed after any manual move, so the slide someone
   just chose gets its full reading time instead of the remainder of a tick
   that was already half spent. */
function heroStartTimer() {
  heroStopTimer();
  if (hero.slides.length < 2 || reducedMotion()) return;
  if (document.hidden) return;
  hero.timer = setInterval(function () { heroGo(hero.index + 1, false); }, HERO_INTERVAL);
}

/* A campaign whose artwork carries its own identity. Everything the app has
   baked into the picture — the collection name, the title, the tagline — is in
   the picture, so the site does not set it again in type beside it. */
function hasArtwork(c) { return !!(c && c.media_url); }

/* Every campaign gets a slide whether or not it has a picture: the words are
   the campaign's identity again, so one without artwork is simply a slide with
   nothing in its media column rather than a hole in the track. */

/* One slide: the campaign's words beside its picture, which is the hero the
   site had before artwork was expected to carry its own typography. The
   difference from then is that every campaign builds one of these and they all
   stay in the document — moving campaign slides the track rather than
   repainting this one, which is what used to look like the page reloading.

   Two links, never nested: the picture is one, the button is another, and both
   carry the same destination from the same resolver. A control inside a link is
   invalid nesting and browsers disagree about which one a click belongs to. */
function campaignLabel(c, i) {
  return blank(c.heading) ? 'Campaign ' + (i + 1) : c.heading;
}
function campaignHref(c) { return c.cta ? c.cta.href : '#/collection'; }
function campaignCtaLabel(c) {
  return c.cta && !blank(c.cta.label) ? c.cta.label : 'Shop Now';
}

/* One campaign's words.
 *
 * No brand tagline in here. It is the same line on every campaign, so it is
 * written once outside the track — inside it, one copy per campaign would slide
 * past the others every time the campaign changed, which reads as the line
 * jumping rather than standing still.
 *
 * has-media is what the stylesheet reads to decide where this campaign's button
 * belongs on a phone: over its photograph when it has one, in the words when it
 * does not. The class travels with the campaign, so the decision is per
 * campaign rather than per breakpoint-at-render-time. */
function campaignSlideHTML(c, i) {
  var label = campaignLabel(c, i);
  var href = campaignHref(c);

  return '<div class="hero-slide' + (hasArtwork(c) ? ' has-media' : '')
    + '" data-slide="' + i + '">'
    + '<div class="hero-copy">'
    + '<h2 class="display">' + esc(label) + '</h2>'
    + (blank(c.subheading) ? '' : '<p class="lede">' + esc(c.subheading) + '</p>')
    + '<a class="pill pill-dark slide-cta" href="' + esc(href) + '">'
    + esc(campaignCtaLabel(c)) + '</a>'
    + '</div>'
    + '</div>';
}

/* The same campaign's picture, in its own track.
 *
 * Two links, never nested: the picture is one, the button over it is another,
 * and both carry the same destination from the same resolver. A control inside
 * a link is invalid nesting and browsers disagree about which one a click
 * belongs to.
 *
 * The overlay button is written for every campaign that has a picture and shown
 * only on a phone, where the button sits on the photograph. It is a second
 * element rather than the copy column's button moved across, because the two
 * tracks are separate subtrees now and an element cannot be in both. The one
 * the breakpoint does not want is display:none, so it is out of the tab order
 * and out of the accessibility tree rather than merely invisible. */
function campaignMediaSlideHTML(c, i) {
  if (!hasArtwork(c)) return '<div class="hero-mslide" data-slide="' + i + '"></div>';

  var label = campaignLabel(c, i);
  var href = campaignHref(c);
  var media = c.media_type === 'video'
    /* The poster stands in until this slide is showing; mounting every
       campaign's film would be several downloads for one hero. */
    ? (c.media_poster_url
      ? '<img src="' + esc(c.media_poster_url) + '" alt="" loading="lazy" decoding="async">' : '')
    : '<img src="' + esc(c.media_url) + '" alt="' + esc(label) + '"'
      + (i === 0 ? ' loading="eager" fetchpriority="high"' : ' loading="lazy"')
      + ' decoding="async">';

  return '<div class="hero-mslide" data-slide="' + i + '">'
    + '<a class="hero-media" href="' + esc(href) + '" aria-label="' + esc(label) + '">'
    + media + '</a>'
    + '<a class="pill slide-cta slide-cta-over" href="' + esc(href) + '" tabindex="-1">'
    + esc(campaignCtaLabel(c)) + '</a>'
    + '</div>';
}

/* Every track the hero moves. Both are written and translated together, so a
   campaign's words and its picture are never a frame apart. */
function heroTracks() {
  return [byId('campaign-track'), byId('campaign-media-track')].filter(Boolean);
}

/* Built once per settings change, not once per slide. This is the whole point
   of the rewrite: the tracks and their pictures stay put, and changing campaign
   moves them. Nothing is torn down and rebuilt, so nothing can flash. */
function renderCampaignTrack(list) {
  var copy = byId('campaign-track');
  var media = byId('campaign-media-track');
  if (copy) copy.innerHTML = list.map(campaignSlideHTML).join('');
  if (media) media.innerHTML = list.map(campaignMediaSlideHTML).join('');

  heroTracks().forEach(function (track) {
    track.style.width = (list.length * 100) + '%';
    Array.prototype.forEach.call(track.children, function (slide) {
      slide.style.width = (100 / list.length) + '%';
    });
  });
}

/* Only the campaign on screen is reachable. Without this a keyboard runs
   through every off-screen campaign's link on the way to the page. */
function syncSlideFocus() {
  heroTracks().forEach(function (track) {
    Array.prototype.forEach.call(track.children, function (slide, i) {
      var on = i === hero.index;
      slide.setAttribute('aria-hidden', on ? 'false' : 'true');
      /* The links inside an off-screen campaign are taken out of the tab order,
         so a keyboard does not walk through every campaign on the way down the
         page. The showing one is reachable exactly as any link is — except the
         button the breakpoint is not using, which stays unreachable because it
         is the same destination twice. */
      Array.prototype.forEach.call(slide.querySelectorAll('a'), function (a) {
        var spare = a.classList.contains('slide-cta-over')
          && getComputedStyle(a).display === 'none';
        if (on && !spare) a.removeAttribute('tabindex');
        else a.setAttribute('tabindex', '-1');
      });
    });
  });
}

/* One campaign ahead. A hero of six is not six downloads. */
function preloadNextCampaign() {
  var track = byId('campaign-media-track');
  if (!track || hero.slides.length < 2) return;
  var next = track.children[(hero.index + 1) % hero.slides.length];
  var img = next && next.querySelector('img');
  if (img && img.loading === 'lazy') img.loading = 'eager';
}

/* A campaign's film is mounted only while it is the one showing, and taken
   down again on the way out — the conservative behaviour the single hero
   already had, kept. */
function syncSlideVideo() {
  var track = byId('campaign-media-track');
  if (!track) return;
  Array.prototype.forEach.call(track.children, function (slide, i) {
    var c = hero.slides[i];
    var existing = slide.querySelector('video');
    if (!c || c.media_type !== 'video' || !hasArtwork(c)) return;
    var holder = slide.querySelector('.hero-media');
    if (!holder) return;
    if (i === hero.index) {
      if (existing) return;
      var poster = slide.querySelector('img');
      if (poster) poster.style.display = 'none';
      holder.insertAdjacentHTML('afterbegin',
        '<video autoplay muted loop playsinline preload="auto"'
        + ' disablepictureinpicture disableremoteplayback'
        + (c.media_poster_url ? ' poster="' + esc(c.media_poster_url) + '"' : '')
        + ' aria-hidden="true">'
        + '<source src="' + esc(c.media_url) + '" type="video/mp4"></video>');
    } else if (existing) {
      existing.parentNode.removeChild(existing);
      var back = slide.querySelector('img');
      if (back) back.style.display = '';
    }
  });
}

function slideTo(index) {
  if (!hero.slides.length) return;
  var shift = 'translateX(-' + (index * (100 / hero.slides.length)) + '%)';
  /* Both tracks, in the same frame. They carry the same number of slides at the
     same widths, so one transform value moves the words and the picture
     together — they cannot drift apart. */
  heroTracks().forEach(function (track) { track.style.transform = shift; });
}

function renderHeroDots() {
  var dots = byId('hero-dots');
  if (!dots) return;
  var many = hero.slides.length > 1;
  dots.classList.toggle('hidden', !many);
  if (!many) { dots.innerHTML = ''; return; }

  dots.innerHTML = hero.slides.map(function (c, i) {
    var on = i === hero.index;
    return '<button class="hero-dot" type="button" role="tab"'
      + ' aria-selected="' + (on ? 'true' : 'false') + '"'
      + ' tabindex="' + (on ? '0' : '-1') + '"'
      + ' data-hero-dot="' + i + '"'
      + ' aria-label="Go to campaign ' + (i + 1) + '"></button>';
  }).join('');
}

function heroGo(index, manual) {
  if (!hero.slides.length) return;
  var next = (index + hero.slides.length) % hero.slides.length;
  if (next === hero.index && hero.slides.length > 1 && !manual) return;
  hero.index = next;

  document.body.setAttribute('data-theme', hero.slides[next].theme || 'default');
  /* The track moves. Nothing is rebuilt, so there is no frame in which the
     hero is empty. */
  slideTo(next);
  syncSlideFocus();
  syncSlideVideo();
  preloadNextCampaign();
  renderHeroDots();
  if (manual) heroStartTimer();
}

/* Bound once for the life of the page. The dots are rewritten on every slide,
   so the listener is delegated rather than attached to buttons that are about
   to be replaced. */
function bindHero() {
  if (hero.bound) return;
  hero.bound = true;

  var dots = byId('hero-dots');
  if (dots) {
    dots.addEventListener('click', function (e) {
      var dot = e.target.closest('[data-hero-dot]');
      if (dot) heroGo(Number(dot.dataset.heroDot), true);
    });
    /* Arrow keys along a tablist, which is what a row of dots announces
       itself as. */
    dots.addEventListener('keydown', function (e) {
      var step = e.key === 'ArrowRight' ? 1 : e.key === 'ArrowLeft' ? -1 : 0;
      if (!step) return;
      e.preventDefault();
      heroGo(hero.index + step, true);
      var now = dots.querySelector('[aria-selected="true"]');
      if (now) now.focus();
    });
  }

  var slot = $('.hero');
  if (slot) {
    var x0 = null, y0 = null;
    slot.addEventListener('touchstart', function (e) {
      if (hero.slides.length < 2) return;
      x0 = e.touches[0].clientX; y0 = e.touches[0].clientY;
    }, { passive: true });
    slot.addEventListener('touchend', function (e) {
      if (x0 === null || hero.slides.length < 2) return;
      var dx = e.changedTouches[0].clientX - x0;
      var dy = e.changedTouches[0].clientY - y0;
      x0 = null;
      /* Horizontal intent only: a vertical drag is the page scrolling. */
      if (Math.abs(dx) < 45 || Math.abs(dx) < Math.abs(dy)) return;
      heroGo(hero.index + (dx < 0 ? 1 : -1), true);
    }, { passive: true });
  }

  /* A hidden tab should not burn through the campaigns unseen. */
  document.addEventListener('visibilitychange', function () {
    if (document.hidden) heroStopTimer();
    else if (hero.slides.length > 1) heroStartTimer();
  });
}

function renderCampaign() {
  var heroSlot = $('.hero-film');
  var row0 = $('.hero-copy .btnrow');
  /* Captured before anything can overwrite it, the same way the editorial hero
     photograph is: without this the swap is one-way, and a settings outage
     after a campaign had rendered would leave the hero with no way back. */
  if (HERO_BTNROW === null && row0) HERO_BTNROW = row0.innerHTML;
  captureHeroDefaults();

  /* Nothing is decided yet. Show neither hero rather than the wrong one: the
     waiting shell holds the hero's footprint on the site's own sand, and no
     film is fetched. The markup starts in this state, so the shell is what the
     first paint draws — deciding it here alone would be deciding it one paint
     too late, which is the flash of "Timeless pieces" this removes.

     The only way out of 'loading' is an answered request: loadSettings() sets
     'ready' on success and 'error' on failure, and runs renderCampaign() again
     either way. There is no path that leaves the shell up for good. */
  var heroEl = $('.hero');
  if (homepageState === 'loading') {
    if (heroEl) heroEl.setAttribute('data-hero-state', 'loading');
    if (heroSlot) heroSlot.setAttribute('data-hero', 'unresolved');
    return;
  }
  if (heroEl) heroEl.setAttribute('data-hero-state', 'resolved');

  var list = activeCampaigns();
  hero.slides = list;
  if (hero.index >= list.length) hero.index = 0;

  var camp = byId('campaign-hero');
  var copy = $('.hero-copy');

  if (!list.length) {
    heroStopTimer();
    if (camp) camp.classList.add('hidden');
    if (copy) copy.classList.remove('hidden');
    if (heroSlot) heroSlot.classList.remove('hidden');
    renderHeroDots();
    paintCampaign(null, false);
    return;
  }

  bindHero();
  /* The copy column and the editorial film belong to the unconfigured
     homepage. A campaign brings its own words and its own picture, so both
     step aside while one is running and come back when none is. */
  if (copy) copy.classList.add('hidden');
  if (heroSlot) heroSlot.classList.add('hidden');
  if (camp) camp.classList.remove('hidden');
  document.body.setAttribute('data-theme',
    (list[hero.index] && list[hero.index].theme) || 'default');
  renderCampaignTrack(list);
  slideTo(hero.index);
  syncSlideFocus();
  syncSlideVideo();
  preloadNextCampaign();

  renderHeroDots();
  heroStartTimer();
}

/* Paints one campaign, or the default hero when given none. Everything that
   used to be the body of renderCampaign, unchanged in what it does to a single
   campaign — the carousel only decides which one is handed here. */
function paintCampaign(c, many) {
  var heroSlot = $('.hero-film');
  var row0 = $('.hero-copy .btnrow');

  document.body.setAttribute('data-theme', (c && c.theme) || 'default');

  if (!c) {
    /* Settled: this hero is the one. Now the film is worth its bytes. */
    if (heroSlot) {
      heroSlot.setAttribute('data-hero', 'default');
      /* A campaign may have replaced the film earlier in this page's life —
         after a settings change, or on the way back from a slide. Put the
         editorial hero's own markup back before asking it to play. */
      if (HERO_DEFAULTS && !byId('hero-video')) heroSlot.innerHTML = HERO_DEFAULTS.film;
    }
    if (HERO_DEFAULTS) {
      var h = byId('hero-heading');
      if (h) h.innerHTML = HERO_DEFAULTS.heading;
      var l0 = $('.hero-copy .lede');
      if (l0) l0.textContent = HERO_DEFAULTS.lede;
    }
    activateDefaultHero();
    if (row0 && HERO_BTNROW !== null) {
      row0.innerHTML = HERO_BTNROW;
      row0.classList.remove('hidden');
    }
    return;
  }

  if (heroSlot) {
    heroSlot.setAttribute('data-hero', 'campaign');
    /* The crossfade. Removed and re-added so the animation restarts on every
       slide; skipped entirely under reduced motion, where the swap is instant. */
    if (many && !reducedMotion()) {
      heroSlot.classList.remove('hero-fade');
      /* Reading offsetWidth is what makes the removal take effect before the
         class goes back on — without it the two changes coalesce and nothing
         animates. */
      void heroSlot.offsetWidth;
      heroSlot.classList.add('hero-fade');
    }
  }

  byId('hero-heading').innerHTML = blank(c.heading)
    ? (HERO_DEFAULTS ? HERO_DEFAULTS.heading : '') : esc(c.heading);
  var lede = $('.hero-copy .lede');
  if (lede) {
    lede.textContent = blank(c.subheading)
      ? (HERO_DEFAULTS ? HERO_DEFAULTS.lede : '') : c.subheading;
  }

  /* A configured campaign owns the hero's call to action completely, including
     the decision to have none at all. The two buttons in the markup belong to
     the unconfigured homepage: they are a fallback, not a floor. Gating this on
     the campaign rather than on its CTA is the whole point — with `none` chosen
     deliberately, an empty row is the answer, and leaving "View the collection"
     standing would be the site overriding Saima.

     The row is emptied and hidden rather than left in place, because .hero-copy
     is a flex column with a 30px gap and an empty child still takes one. */
  /* Where the campaign's one call to action lives.
 *
 * A configured campaign has exactly zero or one — the contract carries a single
 * cta_label and a single destination, so there is no second button to place and
 * none is invented here.
 *
 * On a wide screen it belongs with the words, in the copy column beside the
 * image. On a phone the two columns wrap and the copy becomes a cream slab
 * sitting above the photograph, which reads as a banner bolted on top of a
 * campaign rather than part of one. So on a phone the button moves onto the
 * image itself, bottom left, over the same gradient the film caption already
 * uses — one editorial module instead of two stacked blocks.
 *
 * One element either way. Rendering it twice and hiding one would duplicate an
 * id, put a phantom link in the accessibility tree, and give analytics two
 * things to count later.
 */
function campaignCtaOnImage() {
  return !!(window.matchMedia && window.matchMedia('(max-width:899px)').matches);
}

function placeCampaignCta(c) {
  var row = $('.hero-copy .btnrow');
  var slot = $('.hero-film');
  var overlay = slot ? slot.querySelector('.campaign-overlay') : null;
  var caption = slot ? slot.querySelector('.film-tag') : null;

  if (overlay) overlay.parentNode.removeChild(overlay);

  /* The campaign owns the row whether or not it has anything to put in it —
     see the note above renderCampaign. */
  if (row) { row.innerHTML = ''; row.classList.add('hidden'); }
  if (caption) caption.classList.remove('hidden');

  if (!c.cta) return;

  var link = '<a class="pill pill-over" id="campaign-cta" href="' + esc(c.cta.href) + '">'
    + esc(c.cta.label) + '</a>';

  if (campaignCtaOnImage() && slot) {
    slot.insertAdjacentHTML('beforeend', '<div class="campaign-overlay">' + link + '</div>');
    /* The legacy caption sits in exactly this corner. Two things bottom-left
       is a collision, and the campaign is the one that was asked for. */
    if (caption) caption.classList.add('hidden');
    return;
  }

  if (row) {
    row.innerHTML = '<a class="pill pill-dark" id="campaign-cta" href="' + esc(c.cta.href) + '">'
      + esc(c.cta.label) + '</a>';
    row.classList.remove('hidden');
  }
}

/* One file, no responsive renditions — campaign media is app-managed and
     arrives as a single public URL. The film keeps the behaviour the Roselle
     one has: muted, inline, its own taps, never wrapped in a link.

     Only the slide on screen has media in the document. That is what keeps a
     hero of four films from being four downloads: the previous slide's video
     element is gone before the next one is created, so the browser is never
     asked for more than the campaign currently showing. */
  var slot = $('.hero-film');
  if (slot) {
    if (c.media_url) {
      var caption = slot.querySelector('.film-tag');
      var media = c.media_type === 'video'
        ? '<video id="hero-video"' + (c.media_poster_url ? ' poster="' + esc(c.media_poster_url) + '"' : '')
          + ' autoplay muted loop playsinline preload="auto" disablepictureinpicture disableremoteplayback'
          + ' aria-label="' + esc(c.heading || 'Campaign film') + '">'
          + '<source src="' + esc(c.media_url) + '" type="video/mp4"></video>'
        : '<img class="campaign-img" src="' + esc(c.media_url) + '" alt="' + esc(c.heading || '') + '">';
      slot.innerHTML = media + (c.cta ? '' : (caption ? caption.outerHTML : ''));
      setupHeroFilm();
    } else if (HERO_DEFAULTS) {
      /* A campaign with words but no picture. The editorial hero comes back
         under it rather than the previous slide's film staying put. */
      slot.innerHTML = HERO_DEFAULTS.film;
      var back = byId('hero-video');
      if (back) delete back.dataset.activated;
      activateDefaultHero();
    }
  }

  /* Last, because swapping the media above rewrites the very slot this places
     the button into. */
  placeCampaignCta(c);
}

function renderGrids() {
  renderHero();
  renderCampaign();
  renderEditsNav();
  applySectionOrder();
  renderCollectionNav();
  renderHomeSections();

  var collection = state.collection ? findCollectionBySlug(state.collection) : null;
  var edit = state.edit ? findEditBySlug(state.edit) : null;
  /* Only once the catalogue has actually arrived: while it is loading every
     slug looks unresolvable, and flashing "not found" at someone whose page is
     still loading would be a lie. */
  var missing = catalogue.status === 'ready'
    && ((!!state.collection && !collection) || (!!state.edit && !edit));

  byId('collection-title').textContent =
    edit ? edit.title : collection ? collection.name : 'The Collection';
  byId('collection-missing').classList.toggle('hidden', !missing);
  byId('collection-grid').classList.toggle('hidden', missing);

  /* A piece in two collections appears on both pages — and once on each, since
     it is one entry in PRODUCTS however many collections name it. */
  /* An edit carries its own selection and its own order, so the availability
     filter does not apply to it — the pieces were chosen, not queried. */
  var shown = missing ? []
    /* Every public piece assigned to the edit, in the app's order. A piece that
       is no longer published simply is not found — the edit shortens rather
       than showing a gap, and no count caps an edit page. */
    : edit ? (edit.product_ids || []).map(findProductById).filter(Boolean)
    : PRODUCTS.filter(function (p) {
        return inCollection(p, collection) && matchesFilter(p, state.filter);
      });
  byId('filters').classList.toggle('hidden', missing || !!edit);
  byId('collection-grid').innerHTML = shown.map(function (p) { return cardHTML(p); }).join('');
  byId('collection-count').textContent =
    missing ? ''
    : catalogue.status === 'loading' ? 'Loading the collection…'
    : catalogue.status === 'error' ? 'We couldn’t load the collection. Please try again.'
    : collectionCount(shown.length);
  Array.prototype.forEach.call(byId('filters').children, function (b) {
    b.setAttribute('aria-pressed', String(b.dataset.filter === state.filter));
  });
}

/* ---------- product ---------- */
var SEEN_SIZES = '(max-width:640px) 45vw, (max-width:1100px) 30vw, 240px';

/* Photographs customers sent in.
 *
 * Shown on the page rather than behind a control: a trust signal nobody opens
 * is not a trust signal. Nothing is said about who they are — no name, no
 * quote, no place — because the app supplies an approved image and nothing
 * else, and inventing the rest would be inventing the customer.
 *
 * With none, the section leaves no trace: the heading, the grid and the space
 * they would occupy are all gone, and the page reads exactly as it did before
 * any of this existed. */
function renderCustomerPhotos(p) {
  var section = byId('pdp-seen');
  var grid = byId('pdp-seen-grid');
  if (!section || !grid) return;

  var shots = (p && p.customerPhotos) || [];
  section.classList.toggle('hidden', shots.length === 0);
  if (!shots.length) { grid.innerHTML = ''; return; }

  grid.innerHTML = shots.map(function (img, i) {
    return '<button class="seen-shot" type="button" data-seen="' + i + '"'
      + ' aria-label="View customer photograph ' + (i + 1) + ' of ' + shots.length + '">'
      + imgHTML(img, SEEN_SIZES, 'loading="lazy" decoding="async"')
      + '</button>';
  }).join('');
}

function renderProduct() {
  var p = findProductBySlug(state.slug);

  /* The product may be unknown because the catalogue has not arrived yet, or
     because it genuinely is not there. Those read very differently to a
     visitor, so say which — and never fall through into the render below with
     nothing to render. */
  var stateEl = byId('pdp-state');
  var pdp = $('#view-product .pdp');
  var also = $('#view-product .also');
  if (!p) {
    stateEl.textContent =
      catalogue.status === 'ready' ? 'We couldn’t find that piece.'
      : catalogue.status === 'error' ? 'We couldn’t load this piece. Please try again.'
      : 'Loading…';
    stateEl.classList.remove('hidden');
    pdp.classList.add('hidden');
    also.classList.add('hidden');
    byId('pdp-seen').classList.add('hidden');
    return;
  }
  stateEl.classList.add('hidden');
  pdp.classList.remove('hidden');
  also.classList.remove('hidden');
  renderCustomerPhotos(p);

  /* A different piece means none of the previous piece's gallery state applies
     — not the viewer's photographs, not its index, not a half-finished swipe,
     and not a scroll lock left behind by a viewer that was never closed
     properly. Done here rather than in the router so it holds however the
     visitor arrived. */
  if (renderedSlug !== state.slug) {
    resetGallery();
    renderedSlug = state.slug;
  }

  var others = PRODUCTS.filter(function (x) { return x.id !== p.id; });
  var shots = p.images;
  if (state.shot >= shots.length) state.shot = 0;

  /* Everything below reuses one <img> across every product the visitor opens,
     so each render has to hand it over completely rather than write over the
     parts it happens to touch. The token is what lets a late callback tell
     whether the element it is about to change is still the one it was fired
     for. */
  pdpRender += 1;

  var hero = byId('pdp-hero');
  var shot = shots[state.shot];

  hero.dataset.render = String(pdpRender);
  /* The previous product may have spent its one fallback. This one starts
     with its own. */
  delete hero.dataset.srcsetRetried;

  /* srcset before src, and this order is load-bearing. Assigning src runs the
     selection algorithm immediately, and if the previous product's srcset were
     still on the element the browser would pick a candidate from it — briefly
     fetching, and possibly showing, a photograph of a different garment. */
  if (shot.srcset) { hero.srcset = shot.srcset; hero.sizes = '(max-width:900px) 100vw, 46vw'; }
  else { hero.removeAttribute('srcset'); hero.removeAttribute('sizes'); }
  hero.src = shot.src;
  hero.alt = shot.alt;
  hero.setAttribute('aria-label', 'View ' + (p.name || 'this piece') + ' larger');

  /* One photograph needs no thumbnail strip. Hiding the container rather than
     just emptying it also removes the gallery's 14px flex gap, which an empty
     strip would otherwise leave under the main image. */
  var thumbs = byId('pdp-thumbs');
  thumbs.classList.toggle('hidden', shots.length < 2);
  thumbs.innerHTML = shots.length < 2 ? '' : shots.map(function (s, i) {
    return '<button data-shot="' + i + '" aria-pressed="' + (state.shot === i) + '" aria-label="View ' + (i + 1) + '">' +
      imgHTML(s, '(max-width:900px) 24vw, 130px',
        'loading="lazy" decoding="async" style="object-position:' + (i === 0 ? '50% 15%' : '50% 30%') + '"') +
      '</button>';
  }).join('');

  byId('pdp-name').textContent = p.name;
  byId('pdp-price').textContent = p.price;
  byId('pdp-status').textContent = p.availabilityLabel;
  byId('pdp-dot').style.background = p.dot;
  byId('pdp-desc').textContent = p.description;

  /* Nothing to say about timing means no line — an empty <p> would still take
     its place in the flex column and leave a gap under the button. The helper
     returns '' rather than null or undefined, so nothing can reach the page as
     the word "undefined". */
  var deliveryEl = byId('pdp-delivery');
  var delivery = getEffectiveFulfillment(p, SETTINGS);
  deliveryEl.textContent = delivery;
  deliveryEl.classList.toggle('hidden', blank(delivery));

  /* A piece with no published sizes shows no size control at all. Not an empty
     row, and emphatically not a fabricated "Custom" button — the app decides
     which sizes exist, and none is a legitimate answer. Such a piece can still
     be added to an inquiry; sizing is then settled in the conversation.

     While SHOW_SIZE_SELECTION is off the same is true of every piece: the
     block goes, heading and note with it, and nothing takes its place. The
     page runs from the description straight to Add to Inquiry. */
  var offerSizes = SHOW_SIZE_SELECTION && p.sizes.length > 0;
  byId('pdp-size-block').classList.toggle('hidden', !offerSizes);
  byId('pdp-sizes').innerHTML = !offerSizes ? '' : p.sizes.map(function (s) {
    return '<button data-size="' + esc(s) + '" aria-pressed="' + (state.size === s) + '">' + esc(s) + '</button>';
  }).join('');

  /* Hiding the block when nothing survives also removes its top rule, which
     would otherwise sit under the delivery note as an unexplained hairline. */
  var specsEl = byId('pdp-specs');
  specsEl.classList.toggle('hidden', p.specs.length === 0);
  /* Several values read as one answer to one question — "Organza, Raw Silk" is
     what the garment is made of — so they are set as a sentence rather than
     broken into chips, which would turn a quiet specification into a filter
     bar. */
  specsEl.innerHTML = p.specs.map(function (r) {
    return '<div><p class="k">' + esc(r.label) + '</p>'
      + '<p class="v">' + esc(r.values.join(', ')) + '</p></div>';
  }).join('');

  /* "Select a size" is only an instruction when a size is actually on offer. */
  var ready = !offerSizes || state.size !== null;
  var inBag = state.bag.some(function (b) { return b.id === p.id; });
  var add = byId('pdp-add');
  add.dataset.state = inBag ? 'added' : (ready ? 'ready' : 'idle');
  add.textContent = inBag ? 'In your inquiry ✓' : (ready ? 'Add to inquiry' : 'Select a size');
  add.disabled = inBag;

  /* With nothing to suggest, the heading and the See More below it would be a
     section about nothing, so the whole block goes. */
  also.classList.toggle('hidden', others.length === 0);
  byId('pdp-related').innerHTML = others.slice(0, 4).map(function (x) { return cardHTML(x, true); }).join('');
}

/* ---------- inquiry ---------- */
var BAG_KEY = 'meraki.inquiry.v1';

/* True while a submission is in flight. Read by renderBag so the button cannot
   be re-enabled underneath a request that is still running. */
var submitting = false;

function saveBag() {
  try { localStorage.setItem(BAG_KEY, JSON.stringify(state.bag)); } catch (e) { /* private mode */ }
}

/* Only the product id and the chosen size are persisted — never a copy of the
   product. Everything a row displays is read from the catalogue at render
   time, so a saved inquiry can never show a stale name, price or photograph.

   Loading deliberately does NOT check ids against PRODUCTS. It used to, which
   meant that if the catalogue were ever momentarily empty — precisely what
   happens while an async fetch is in flight — every entry looked unknown, the
   bag was emptied, and the next save wrote that empty bag over the customer's
   inquiry. Persistence and validation are separate concerns: an entry is kept
   until the visitor removes it. */
function loadBag() {
  try {
    var raw = localStorage.getItem(BAG_KEY);
    var saved = raw ? JSON.parse(raw) : [];
    if (!Array.isArray(saved)) return;
    state.bag = saved
      .filter(function (b) { return b && b.id; })
      .map(function (b) { return { id: b.id, size: b.size }; });
  } catch (e) { state.bag = []; }
}

/* A saved entry whose product is not in the catalogue is still shown and still
   removable — it is never dropped on the visitor's behalf. Which message it
   carries depends on whether the catalogue has finished loading. */
function bagRowHTML(b, i) {
  var p = findBagProduct(b.id);
  var name = p ? p.name
    : catalogue.status === 'ready' ? 'No longer available'
    : catalogue.status === 'error' ? 'Couldn’t load this piece'
    : 'Loading…';
  /* Both halves are optional: the price is unknown until the catalogue lands,
     and the size is genuinely absent for a piece that publishes none. Built
     from whatever is actually known rather than from a fixed template with
     holes in it. */
  var bits = [];
  if (p && !blank(p.price)) bits.push(esc(p.price));
  if (!blank(b.size)) bits.push('Size ' + esc(b.size));
  var line = bits.join(' · ');

  return '<div class="bagrow"><div class="thumb">' +
    (p ? imgHTML(p.images[0], '92px', 'loading="lazy" decoding="async"') : '') + '</div>' +
    '<div class="info"><p class="name">' + esc(name) + '</p>' +
    (line ? '<p class="price">' + line + '</p>' : '') +
    '<p class="status" style="margin-top:2px">' + esc(p ? p.availabilityLabel : '') + '</p></div>' +
    '<button class="remove" data-remove="' + i + '" aria-label="Remove ' + esc(name) + ' from your inquiry">Remove</button></div>';
}

function renderBag() {
  byId('bag-count').textContent = String(state.bag.length);
  var n = state.bag.length;
  byId('bag-label').textContent = n === 0 ? 'Nothing selected yet'
    : n + (n === 1 ? ' look selected' : ' looks selected');

  byId('bag-list').innerHTML = n === 0
    ? '<div class="empty"><p class="body">You haven\'t selected any looks yet.</p>' +
      '<button class="pill pill-ghost" style="padding:14px 28px" data-nav="#/collection">Browse the collection</button></div>'
    : state.bag.map(function (b, i) { return bagRowHTML(b, i); }).join('');

  var submit = byId('inq-submit');
  submit.dataset.ready = String(n > 0);
  /* Never re-enable mid-flight: renderBag runs for reasons unrelated to the
     submission, and an enabled button during a request invites a second one. */
  submit.disabled = n === 0 || submitting;
}

/* Everything the atelier needs to answer an inquiry, in the shape
   POST /api/inquiries expects.

   Deliberately thin: product ids and the requested size, nothing else. Name,
   sku, slug and price are re-read from the database server-side, because a
   payload that has been sitting in a browser tab — or edited by hand — is a
   request, not a source of truth. The id identifies the piece; everything
   descriptive is the server's to decide. */
function inquiryPayload(form) {
  return {
    client_submission_id: submissionId(),
    customer: {
      name: form.name.value.trim(),
      phone: form.phone.value.trim(),
      email: form.email.value.trim(),
      /* Inquiry-level: one state, one size, however many pieces. */
      state: form.state.value,
      preferred_size: form.preferred_size.value,
      note: form.note.value.trim()
    },
    items: state.bag.map(function (b) {
      var p = findBagProduct(b.id);
      /* Product id only. Size is asked once for the whole inquiry now, so
         nothing per-item is sent — inquiry_items.requested_size stays for the
         records written before that was true. */
      return { product_id: p ? p.id : b.id };
    })
  };
}

/* ---------- inquiry submission ---------- */

/* One id per submission *attempt*, held across retries on purpose. If the
   network drops after the server has committed, the customer's retry carries
   the same id, the unique constraint catches it, and they get the original
   inquiry back instead of a second one landing in Saima's inbox. Cleared only
   once a submission has actually succeeded. */
var SUBMISSION_KEY = 'meraki.inquiry.submission';
var currentSubmissionId = null;

function uuidv4() {
  if (window.crypto && crypto.randomUUID) return crypto.randomUUID();
  /* Older Safari. getRandomValues is available far earlier than randomUUID. */
  var b = new Uint8Array(16);
  (window.crypto || {}).getRandomValues
    ? crypto.getRandomValues(b)
    : (function () { for (var i = 0; i < 16; i++) b[i] = Math.floor(Math.random() * 256); })();
  b[6] = (b[6] & 0x0f) | 0x40;
  b[8] = (b[8] & 0x3f) | 0x80;
  var h = [];
  for (var i = 0; i < 16; i++) h.push((b[i] + 0x100).toString(16).slice(1));
  return h.slice(0, 4).join('') + '-' + h.slice(4, 6).join('') + '-' + h.slice(6, 8).join('') +
    '-' + h.slice(8, 10).join('') + '-' + h.slice(10, 16).join('');
}

function submissionId() {
  if (!currentSubmissionId) {
    /* Survives a reload mid-retry, so a customer who refreshes after a timeout
       still deduplicates against the attempt that may have landed. */
    try { currentSubmissionId = localStorage.getItem(SUBMISSION_KEY) || null; } catch (e) {}
    if (!currentSubmissionId) {
      currentSubmissionId = uuidv4();
      try { localStorage.setItem(SUBMISSION_KEY, currentSubmissionId); } catch (e) {}
    }
  }
  return currentSubmissionId;
}

function retireSubmissionId() {
  currentSubmissionId = null;
  try { localStorage.removeItem(SUBMISSION_KEY); } catch (e) {}
}

/* ---------- validation ---------- */

/* US only for now. The customer types whatever shape feels natural and it is
   reduced to one canonical form here; the same rule runs again server-side,
   which is the one that counts. Returns '+1XXXXXXXXXX' or null. */
function normalizeUsPhone(raw) {
  if (blank(raw)) return null;
  var s = String(raw).trim();
  if (s.length > 40) return null;
  if (/[a-z]/i.test(s)) return null;              /* letters, extensions */
  if (/[^0-9+()\-.\s]/.test(s)) return null;
  var digits = s.replace(/\D/g, '');
  if (digits.length === 11 && digits.charAt(0) === '1') digits = digits.slice(1);
  if (digits.length !== 10) return null;
  if (/^[01]/.test(digits) || /^[01]/.test(digits.slice(3))) return null;
  return '+1' + digits;
}

var EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

function setFieldError(name, message) {
  var el = byId('err-' + name);
  var input = $('#inquiry-form [name="' + name + '"]');
  if (el) {
    el.textContent = message || '';
    el.classList.toggle('hidden', !message);
  }
  if (input) {
    /* Not colour alone: the message is real text beside the field, and the
       state is announced. */
    if (message) input.setAttribute('aria-invalid', 'true');
    else input.removeAttribute('aria-invalid');
  }
}

function clearFieldErrors() {
  ['name', 'phone', 'email', 'state', 'preferred_size', 'note']
    .forEach(function (n) { setFieldError(n, ''); });
  var box = byId('inq-error');
  if (box) { box.textContent = ''; box.classList.add('hidden'); }
}

/* Returns the first invalid field name, or null. Messages say what to do rather
   than what went wrong. */
function validateInquiryForm(form) {
  clearFieldErrors();
  var first = null;
  var fail = function (n, m) { setFieldError(n, m); if (!first) first = n; };

  if (blank(form.name.value)) fail('name', 'Please tell us your name.');

  if (blank(form.phone.value)) fail('phone', 'Please add a phone number so we can reach you.');
  else if (!normalizeUsPhone(form.phone.value)) fail('phone', 'Enter a valid 10-digit U.S. phone number.');

  if (!blank(form.email.value) && !EMAIL_RE.test(form.email.value.trim().toLowerCase())) {
    fail('email', 'This email address doesn\'t look right.');
  }

  if (blank(form.state.value)) fail('state', 'Please choose your state.');
  if (blank(form.preferred_size.value)) fail('preferred_size', 'Please choose a preferred size.');

  if (form.note.value.length > 2000) fail('note', 'Please keep this under 2000 characters.');

  return first;
}

function focusField(name) {
  var input = $('#inquiry-form [name="' + name + '"]');
  if (!input) return;
  try { input.focus({ preventScroll: true }); } catch (e) { input.focus(); }
  if (input.scrollIntoView) input.scrollIntoView({ block: 'center', behavior: 'smooth' });
}

function setSubmitting(on) {
  var btn = byId('inq-submit');
  if (!btn) return;
  btn.disabled = on || state.bag.length === 0;
  btn.dataset.sending = String(on);
  btn.textContent = on ? 'Sending…' : 'Request these looks';
}

function showFormError(message) {
  var box = byId('inq-error');
  if (!box) return;
  box.textContent = message;
  box.classList.remove('hidden');
}

/* ---------- image viewer ---------- */

/* Opening a photograph is for looking at the embroidery, so the viewer loads
   the master rather than a rendition — image.src is the master, and no srcset
   is set here on purpose. The responsive selection on the page itself is
   untouched; this is a separate, deliberate request for the largest source.

   Only PDP gallery images open it. A catalogue card is a link to a product and
   stays one. */
var lightbox = { open: false, shots: [], index: 0, returnFocus: null, scrollY: 0 };

/* Which product the PDP is currently rendered for, and a counter that changes
   on every render. Between them they let anything asynchronous work out
   whether the page still belongs to it. */
var renderedSlug = null;
var pdpRender = 0;
var touchStart = null;

/* Hand the gallery over to a different product.
 *
 * Called on every change of piece, whether or not the viewer was closed
 * properly — the point is that it cannot be left holding photographs of a
 * garment that is no longer on screen. Safe to call when nothing is open. */
function resetGallery() {
  if (lightbox.open) closeLightbox();
  else if (document.body.style.position === 'fixed') unlockPageScroll();   /* left locked somehow */

  lightbox.shots = [];
  lightbox.index = 0;
  lightbox.returnFocus = null;
  touchStart = null;

  var img = byId('lb-img');
  if (img) { img.removeAttribute('src'); img.removeAttribute('srcset'); img.alt = ''; }
  byId('lightbox').classList.add('hidden');
  byId('lb-count').textContent = '';
}

function lbEl(id) { return byId(id); }

/* iOS ignores `overflow:hidden` on body often enough to be unreliable, so the
   page is pinned by position and put back exactly where it was on close. */
function lockPageScroll() {
  lightbox.scrollY = window.scrollY || window.pageYOffset || 0;
  document.body.style.position = 'fixed';
  document.body.style.top = -lightbox.scrollY + 'px';
  document.body.style.left = '0';
  document.body.style.right = '0';
  document.body.style.width = '100%';
}

function unlockPageScroll() {
  document.body.style.position = '';
  document.body.style.top = '';
  document.body.style.left = '';
  document.body.style.right = '';
  document.body.style.width = '';
  /* The stylesheet sets scroll-behavior:smooth, which makes this restore an
     animation that races the layout coming back — the page lands somewhere
     short of where it started. Putting someone back where they were is not a
     journey, so it is done instantly and the preference is put back. */
  var root = document.documentElement;
  var prior = root.style.scrollBehavior;
  root.style.scrollBehavior = 'auto';
  /* Two goes on purpose. Un-fixing the body does not restore the document's
     full height synchronously, so the first scroll can still be clamped
     against the collapsed page; the second runs once layout has settled and
     lands exactly. Reading scrollHeight forces the reflow in between. */
  var y = lightbox.scrollY;
  void root.scrollHeight;
  window.scrollTo(0, y);
  requestAnimationFrame(function () {
    window.scrollTo(0, y);
    root.style.scrollBehavior = prior;
  });
}

function renderLightbox() {
  var shot = lightbox.shots[lightbox.index];
  if (!shot) return;
  var img = lbEl('lb-img');
  /* The master, at full size. No srcset: a rendition is the wrong answer to
     "let me look closely". */
  img.removeAttribute('srcset');
  img.removeAttribute('sizes');
  img.src = shot.src;
  img.alt = shot.alt || '';

  var many = lightbox.shots.length > 1;
  lbEl('lb-prev').classList.toggle('hidden', !many);
  lbEl('lb-next').classList.toggle('hidden', !many);
  lbEl('lb-count').textContent = many ? (lightbox.index + 1) + ' / ' + lightbox.shots.length : '';
}

function openLightbox(shots, index, trigger) {
  if (!shots || !shots.length) return;
  lightbox.shots = shots;
  lightbox.index = Math.max(0, Math.min(index || 0, shots.length - 1));
  lightbox.returnFocus = trigger || null;
  lightbox.open = true;

  lockPageScroll();
  byId('lightbox').classList.remove('hidden');
  renderLightbox();
  /* Focus lands on Close so the first key press does the obvious thing, and so
     focus is never left sitting behind the overlay. */
  lbEl('lb-close').focus();
}

function closeLightbox() {
  if (!lightbox.open) return;
  lightbox.open = false;
  byId('lightbox').classList.add('hidden');
  /* Release the master so a long browse does not hold every photograph open. */
  lbEl('lb-img').removeAttribute('src');
  unlockPageScroll();
  if (lightbox.returnFocus && lightbox.returnFocus.focus) lightbox.returnFocus.focus();
  lightbox.returnFocus = null;
}

function stepLightbox(delta) {
  if (!lightbox.open || lightbox.shots.length < 2) return;
  var n = lightbox.shots.length;
  lightbox.index = (lightbox.index + delta + n) % n;   /* wraps both ways */
  renderLightbox();
}

/* The customer photographs of the piece currently on screen. Deliberately its
   own accessor beside currentGalleryShots(): the two sets are never appended,
   never interleaved, and the viewer is handed one or the other — so stepping
   through customer photographs cannot wander into the studio ones. */
function currentCustomerShots() {
  var p = findProductBySlug(state.slug);
  return (p && p.customerPhotos) || [];
}

/* The photographs of the piece currently on screen. */
function currentGalleryShots() {
  var p = findProductBySlug(state.slug);
  return p ? p.images : [];
}

/* The main photograph carries button semantics in the markup, so it also has
   to answer to the keys a button answers to. */
byId('pdp-hero').addEventListener('keydown', function (e) {
  if (e.key !== 'Enter' && e.key !== ' ' && e.key !== 'Spacebar') return;
  e.preventDefault();
  openLightbox(currentGalleryShots(), state.shot, byId('pdp-hero'));
});

byId('lb-close').addEventListener('click', closeLightbox);
byId('lb-prev').addEventListener('click', function () { stepLightbox(-1); });
byId('lb-next').addEventListener('click', function () { stepLightbox(1); });

/* Backdrop closes; the photograph itself does not, so an attempt to pinch or
   pan cannot dismiss it by accident. */
byId('lightbox').addEventListener('click', function (e) {
  if (e.target === this || e.target === byId('lb-stage')) closeLightbox();
});

document.addEventListener('keydown', function (e) {
  if (!lightbox.open) return;
  if (e.key === 'Escape') { closeLightbox(); return; }
  if (e.key === 'ArrowLeft') { stepLightbox(-1); return; }
  if (e.key === 'ArrowRight') { stepLightbox(1); }
});

/* Swipe between photographs. Deliberately crude: one axis, one threshold, and
   it defers to a vertical gesture so panning a zoomed image still works.
   Declared with the rest of the viewer's state so resetGallery can clear it. */
byId('lb-stage').addEventListener('touchstart', function (e) {
  if (e.touches.length !== 1) { touchStart = null; return; }   /* a pinch, leave it alone */
  touchStart = { x: e.touches[0].clientX, y: e.touches[0].clientY };
}, { passive: true });

byId('lb-stage').addEventListener('touchend', function (e) {
  if (!touchStart || !e.changedTouches.length) return;
  var dx = e.changedTouches[0].clientX - touchStart.x;
  var dy = e.changedTouches[0].clientY - touchStart.y;
  touchStart = null;
  if (Math.abs(dx) > 50 && Math.abs(dx) > Math.abs(dy) * 1.5) stepLightbox(dx < 0 ? 1 : -1);
}, { passive: true });

/* ---------- routing ---------- */
/* ---------------------------------------------------------------------------
 * Consent, and the Meta Pixel that depends on it.
 *
 * The pixel used to sit in <head> and fire while the page parsed, which set
 * _fbp before the visitor had been asked anything. Nothing Meta-related now
 * happens until someone has said yes: no script tag, no init, no event.
 *
 * The whole thing is one small module on purpose. Analytics that is scattered
 * is analytics nobody can audit, and this is the part of the site a visitor is
 * most entitled to have an accurate answer about.
 * ------------------------------------------------------------------------- */

var CONSENT_KEY = 'meraki.consent.v1';
var META_PIXEL_ID = '1110330678318896';

/* 'accepted' | 'declined' | null for not yet asked. Anything else in storage —
   an older value, something hand-edited — reads as unanswered, which errs
   towards asking again rather than towards tracking. */
function readConsent() {
  try {
    var v = localStorage.getItem(CONSENT_KEY);
    return v === 'accepted' || v === 'declined' ? v : null;
  } catch (e) { return null; }   /* private mode: treat as unanswered */
}

var consent = readConsent();

function saveConsent(value) {
  consent = value;
  try { localStorage.setItem(CONSENT_KEY, value); } catch (e) { /* private mode */ }
}

/* Loaded once per page life. Meta's own snippet is idempotent, but init is not,
   so the flag guards the init as much as the script tag. */
var pixelReady = false;

function initMetaPixel() {
  if (pixelReady || consent !== 'accepted') return false;
  try {
    /* Meta's loader, unchanged in what it does — only in when it runs. */
    /* eslint-disable */
    !function (f, b, e, v, n, t, s) {
      if (f.fbq) return; n = f.fbq = function () {
        n.callMethod ? n.callMethod.apply(n, arguments) : n.queue.push(arguments);
      };
      if (!f._fbq) f._fbq = n; n.push = n; n.loaded = !0; n.version = '2.0';
      n.queue = []; t = b.createElement(e); t.async = !0;
      t.src = v; s = b.getElementsByTagName(e)[0];
      s.parentNode.insertBefore(t, s);
    }(window, document, 'script', 'https://connect.facebook.net/en_US/fbevents.js');
    /* eslint-enable */
    if (typeof window.fbq !== 'function') return false;
    window.fbq('init', META_PIXEL_ID);
    pixelReady = true;
  } catch (e) {
    /* A blocked script, an ad blocker, a CSP — none of it is the page's
       problem. The site does not depend on Meta for anything. */
    pixelReady = false;
  }
  return pixelReady;
}

/* Every Meta event on the site goes through here. Returns whether it actually
   went, which is what the dedupe keys are set from — an event that never left
   should not be remembered as sent. */
function trackMetaEvent(name, params) {
  if (consent !== 'accepted' || !pixelReady) return false;
  try {
    if (typeof window.fbq !== 'function') return false;
    if (params) window.fbq('track', name, params);
    else window.fbq('track', name);
    return true;
  } catch (e) { return false; }
}

/* The route as Meta should see it. The same hash the router already trusts —
   there is no second interpretation of where the visitor is. */
function routeKey() {
  return location.hash.replace(/^#\/?/, '') || 'home';
}

/* What has already been reported for the navigation the visitor is on.
   route() runs more than once per URL by design — the catalogue landing calls
   it, an error calls it, a sent inquiry calls it — so these are keyed on the
   route rather than counted per call. Cleared by moving somewhere else, which
   is why leaving a piece and coming back reports it again: that is a second
   visit to it, not a re-render of the first. */
var lastPageViewKey = null;
var lastViewContentKey = null;

function reportViewContent(key) {
  if (key.indexOf('product/') !== 0) { lastViewContentKey = null; return; }
  if (lastViewContentKey === key) return;

  /* The catalogue may not have answered yet on a direct load. Reporting a
     piece we cannot name would be worse than reporting it a moment later, and
     the key stays unset so the next route() through here still sends it. */
  var p = findProductBySlug(state.slug);
  if (!p) return;

  var params = {
    content_type: 'product',
    content_name: p.name,
    /* The app's own reference where there is one, its id otherwise. Never
       invented, and never the slug. */
    content_ids: [p.sku || p.id]
  };
  if (typeof p.priceValue === 'number') {
    params.value = p.priceValue;
    params.currency = p.currency || 'USD';
  }
  if (trackMetaEvent('ViewContent', params)) lastViewContentKey = key;
}

/* One PageView per real navigation, plus ViewContent when that navigation is a
   piece. Nothing here fires for a lightbox, a modal, a resize or a re-render,
   because none of those change the hash. */
function reportRouteView() {
  if (consent !== 'accepted') return;
  if (!pixelReady && !initMetaPixel()) return;

  var key = routeKey();
  if (lastPageViewKey !== key && trackMetaEvent('PageView')) lastPageViewKey = key;
  reportViewContent(key);
}

/* ---------- the consent UI ---------- */

function showConsentBanner(show) {
  var el = byId('consent');
  if (!el) return;
  el.classList.toggle('hidden', !show);
}

function answerConsent(value) {
  saveConsent(value);
  showConsentBanner(false);
  if (value === 'accepted') {
    /* Accepting on a product page owes them both events for where they already
       are, without making them navigate again to be counted. */
    initMetaPixel();
    reportRouteView();
  }
  /* Declining sends nothing and unsends nothing. Whatever a previous accept
     already dispatched has left; from here trackMetaEvent simply refuses. */
}

(function setupConsent() {
  var accept = byId('consent-accept');
  var decline = byId('consent-decline');
  var prefs = byId('cookie-prefs');
  if (accept) accept.addEventListener('click', function () { answerConsent('accepted'); });
  if (decline) decline.addEventListener('click', function () { answerConsent('declined'); });
  if (prefs) {
    prefs.addEventListener('click', function () {
      showConsentBanner(true);
      /* Asked for it, so put them in it — the first choice takes focus. */
      var first = byId('consent-decline');
      if (first) first.focus();
    });
  }
  /* Reading the banner should not require answering it first. */
  var link = byId('consent-privacy');
  if (link) link.addEventListener('click', function () { showConsentBanner(false); });

  if (consent === null) showConsentBanner(true);
  else if (consent === 'accepted') initMetaPixel();
})();

var VIEWS = ['home', 'collection', 'product', 'inquiry', 'privacy', 'story'];

function show(view) {
  VIEWS.forEach(function (v) { byId('view-' + v).classList.toggle('hidden', v !== view); });
}

/* The router proper is applyRoute; route() is what everything calls, so that
   every path into a new view reports it exactly once. */
function route() {
  applyRoute();
  reportRouteView();
}

function applyRoute() {
  var hash = location.hash.replace(/^#\/?/, '');

  /* Leaving the inquiry page retires the thank-you screen, so the next visit
     starts a fresh inquiry rather than showing the old confirmation forever. */
  if (hash !== 'inquiry') state.sent = false;

  if (hash.indexOf('product/') === 0) {
    state.slug = decodeURIComponent(hash.slice(8));
    state.size = null; state.shot = 0;
    renderProduct(); show('product'); window.scrollTo(0, 0); return;
  }
  /* A curated edit. Deliberately its own route rather than a collection with
     a different name: an edit may draw from several collections or from none,
     and pointing its link at a collection page would show the wrong pieces. */
  if (hash.indexOf('edit/') === 0) {
    state.edit = decodeURIComponent(hash.slice(5));
    state.collection = null;
    state.filter = 'all';
    renderGrids(); show('collection'); window.scrollTo(0, 0); return;
  }
  /* A collection of its own. The slug is resolved against the live catalogue
     in renderGrids(), which also handles one that no longer resolves. */
  if (hash.indexOf('collection/') === 0) {
    state.collection = decodeURIComponent(hash.slice(11));
    state.edit = null;
    state.filter = 'all';
    renderGrids(); show('collection'); window.scrollTo(0, 0); return;
  }
  if (hash === 'collection' || hash === 'ready' || hash === 'made-to-order') {
    state.collection = null;
    state.edit = null;
    state.filter = hash === 'ready' ? 'ready' : (hash === 'made-to-order' ? 'mto' : 'all');
    renderGrids(); show('collection'); window.scrollTo(0, 0); return;
  }
  /* Reachable whatever the visitor decided, and whether or not they decided. */
  if (hash === 'privacy') {
    show('privacy'); window.scrollTo(0, 0); return;
  }
  if (hash === 'inquiry') {
    byId('inq-form-wrap').classList.toggle('hidden', state.sent);
    byId('inq-thanks').classList.toggle('hidden', !state.sent);
    renderBag(); show('inquiry'); window.scrollTo(0, 0); return;
  }

  /* Our Story has a page of its own now that the homepage band it used to
     scroll to has become the customer photographs. Same address as before, so
     the header link and any shared URL still land on the same words. */
  if (hash === 'story') {
    show('story'); window.scrollTo(0, 0); return;
  }

  show('home');
  window.scrollTo(0, 0);
}
/* ---------- events (delegated) ---------- */
document.addEventListener('click', function (e) {
  if (!e.target || !e.target.closest) return;

  var nav = e.target.closest('[data-nav]');
  if (nav) { location.hash = nav.dataset.nav; return; }

  /* A thumbnail chooses the photograph; it does not open the viewer.
     Doing both meant a visitor who only wanted to see another angle was put
     into a full-screen viewer they had to dismiss — a tap to look became two
     taps and a way back out. Choosing and magnifying are separate intentions,
     so they are separate gestures: the thumbnail sets the main image, and the
     main image is what opens the viewer. */
  /* Customer photographs open into the same viewer with their own set. The
     studio photographs are not appended, so next and previous stay inside the
     photographs customers actually sent. */
  var seen = e.target.closest('[data-seen]');
  if (seen) {
    openLightbox(currentCustomerShots(), Number(seen.dataset.seen), seen);
    return;
  }

  var shot = e.target.closest('[data-shot]');
  if (shot) {
    state.shot = Number(shot.dataset.shot);
    renderProduct();
    return;
  }

  /* Only the PDP gallery opens the viewer. A catalogue card is a link to a
     product and stays one — it is not caught here at all. */
  if (e.target.id === 'pdp-hero') {
    openLightbox(currentGalleryShots(), state.shot, byId('pdp-hero'));
    return;
  }

  var size = e.target.closest('[data-size]');
  if (size) { state.size = size.dataset.size; renderProduct(); return; }

  var filt = e.target.closest('[data-filter]');
  if (filt) { state.filter = filt.dataset.filter; renderGrids(); return; }

  var rm = e.target.closest('[data-remove]');
  if (rm) { state.bag.splice(Number(rm.dataset.remove), 1); saveBag(); renderBag(); return; }

  if (e.target.closest('#pdp-add')) {
    var p = findProductBySlug(state.slug);
    if (!p || state.bag.some(function (b) { return b.id === p.id; })) return;
    /* A size is required only when one was actually offered. */
    var offered = SHOW_SIZE_SELECTION && p.sizes.length > 0;
    if (offered && !state.size) return;
    state.bag.push({ id: p.id, size: offered ? state.size : null });   /* identity is the id, never the slug */
    saveBag(); renderProduct(); renderBag();
  }
});

var INQUIRIES_ENDPOINT = '/api/inquiries';

/* Meta's Lead event, reported once per inquiry that actually reached the
   atelier.

   Keyed on the submission id rather than a bare flag, because that id is what
   makes one *logical* inquiry one thing: it survives retries and a reload
   mid-retry, so a submission that lands after a dropped connection reports
   once, not twice.

   Everything here is wrapped: a blocked pixel, an ad blocker, a script that
   never loaded, or an fbq that throws must not cost the customer their
   thank-you screen. Analytics is the least important thing on this page. */
var leadReported = null;

function reportLead(id) {
  if (!id || leadReported === id) return;
  leadReported = id;
  /* Consent is checked inside trackMetaEvent, so a declining customer's
     inquiry still completes in exactly the same way — it is simply not
     reported. The id is marked used either way: whether Meta heard about this
     inquiry is not a reason to consider reporting it again. */
  trackMetaEvent('Lead');
}

/* The bag is cleared and the thank-you shown only after the server has
   confirmed. A failure leaves everything exactly as the customer left it —
   their looks, their typed answers — so retrying costs them nothing. */
byId('inquiry-form').addEventListener('submit', function (e) {
  e.preventDefault();
  var form = e.target;

  if (submitting || !state.bag.length) return;

  var invalid = validateInquiryForm(form);
  if (invalid) { focusField(invalid); return; }

  submitting = true;
  setSubmitting(true);

  var payload = inquiryPayload(form);

  fetch(INQUIRIES_ENDPOINT, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
    body: JSON.stringify(payload)
  })
    .then(function (res) {
      return res.json().catch(function () { return null; }).then(function (data) {
        return { status: res.status, ok: res.ok, data: data };
      });
    })
    .then(function (r) {
      if (!r.ok || !r.data || r.data.ok !== true) throw r;

      /* Confirmed saved. A duplicate is this same inquiry arriving twice — the
         customer only enquired once, so Meta hears about it once. The id comes
         from the payload rather than the global, which is retired just below. */
      if (r.data.duplicate !== true) reportLead(payload.client_submission_id);

      /* Committed. Only now is anything thrown away — and the submission id is
         retired so the next inquiry starts a new one. */
      retireSubmissionId();
      state.sent = true;
      state.bag = [];
      saveBag();
      form.reset();
      clearFieldErrors();
      renderBag();
      route();
    })
    .catch(function (r) {
      /* The bag survives, the form keeps its values, and the same submission id
         is reused on the next attempt. */
      var code = r && r.data && r.data.error;
      showFormError(
        code === 'invalid_phone' ? 'Enter a valid 10-digit U.S. phone number.'
        : code === 'invalid_email' ? 'This email address doesn\'t look right.'
        : code === 'name_required' ? 'Please tell us your name.'
        : (code === 'state_required' || code === 'invalid_state') ? 'Please choose your state.'
        : (code === 'preferred_size_required' || code === 'invalid_preferred_size') ? 'Please choose a preferred size.'
        : code === 'product_unavailable' ? 'One of these pieces is no longer available. Please remove it and try again.'
        : code === 'too_many_requests' ? 'That was a lot of tries at once. Please wait a moment and send again.'
        : 'We couldn\'t send your inquiry just now. Please try again in a moment.');
      if (code === 'invalid_phone') { setFieldError('phone', 'Enter a valid 10-digit U.S. phone number.'); focusField('phone'); }
      if (code === 'invalid_email') { setFieldError('email', 'This email address doesn\'t look right.'); focusField('email'); }
      if (code === 'state_required' || code === 'invalid_state') { setFieldError('state', 'Please choose your state.'); focusField('state'); }
      if (code === 'preferred_size_required' || code === 'invalid_preferred_size') { setFieldError('preferred_size', 'Please choose a preferred size.'); focusField('preferred_size'); }
    })
    .then(function () {
      submitting = false;
      setSubmitting(false);
    });
});

/* Validate on the way out of a field rather than on every keystroke: nobody
   wants to be told their phone number is wrong while they are still typing it. */
/* A select answers on change rather than on blur — the error should clear the
   moment a choice is made, not when focus happens to leave. */
['state', 'preferred_size'].forEach(function (name) {
  var el = $('#inquiry-form [name="' + name + '"]');
  if (el) el.addEventListener('change', function () { if (!blank(el.value)) setFieldError(name, ''); });
});

['name', 'phone', 'email'].forEach(function (name) {
  var input = $('#inquiry-form [name="' + name + '"]');
  if (!input) return;
  input.addEventListener('blur', function () {
    if (blank(input.value)) { if (name !== 'email') setFieldError(name, ''); return; }
    if (name === 'phone' && !normalizeUsPhone(input.value)) {
      setFieldError('phone', 'Enter a valid 10-digit U.S. phone number.');
    } else if (name === 'email' && !EMAIL_RE.test(input.value.trim().toLowerCase())) {
      setFieldError('email', 'This email address doesn\'t look right.');
    } else {
      setFieldError(name, '');
    }
  });
});

/* Fetch the published catalogue and hand every product through the same
   mapProduct() the fixtures went through. There is deliberately no embedded
   fallback catalogue: if this fails the storefront says so, rather than
   quietly serving a copy of the products baked in at deploy time. */
function loadCatalogue() {
  setCatalogueState('loading');

  return fetch(PRODUCTS_ENDPOINT, { headers: { Accept: 'application/json' } })
    .then(function (res) {
      if (!res.ok) throw new Error('HTTP ' + res.status);
      return res.json();
    })
    .then(function (payload) {
      var mapped = mapProducts(payload && payload.products);
      PRODUCTS.length = 0;
      PRODUCTS.push.apply(PRODUCTS, mapped);
      setCatalogueState('ready');
    })
    .catch(function (err) {
      PRODUCTS.length = 0;
      setCatalogueState('error', err);
    });
}

/* ---------- website settings ---------- */

/* Fill an element with text, or hide it. Every settings-driven line on the page
   goes through here, so "Saima has not filled this in" always renders the same
   way: the line is absent, never an empty label, a dangling separator or a
   placeholder standing in for a real answer. The prefix is the punctuation that
   only makes sense once there is something to punctuate. */
function setSettingLine(id, value, prefix) {
  var el = byId(id);
  if (!el) return null;
  var empty = blank(value);
  el.textContent = empty ? '' : (prefix || '') + String(value).trim();
  el.classList.toggle('hidden', empty);
  return empty ? null : el;
}

/* The app stores WhatsApp as international digits and renders it as "+digits".
   wa.me wants the digits alone, so anything a human may have typed around them
   — plus, spaces, brackets, dashes — is stripped here rather than assumed
   absent. No digits means no link: a bare https://wa.me/ is a broken promise,
   not a contact detail. */
function whatsappHref(value) {
  var digits = blank(value) ? '' : String(value).replace(/\D+/g, '');
  return digits ? 'https://wa.me/' + digits : null;
}

/* Saved as a full profile URL by the app, but a bare handle or a scheme-less
   host would both otherwise resolve as a relative path on this site. */
function externalHref(value) {
  if (blank(value)) return null;
  var url = String(value).trim();
  return /^https?:\/\//i.test(url) ? url : 'https://' + url.replace(/^\/+/, '');
}

function setContactLink(id, href, label) {
  var el = byId(id);
  if (!el) return false;
  if (!href) {
    el.classList.add('hidden');
    el.removeAttribute('href');
    return false;
  }
  el.href = href;
  if (label) el.textContent = label;
  el.classList.remove('hidden');
  return true;
}

/* Everything Saima maintains in the app, written onto the page in one place.
   Called once at load with blank settings and again when the fetch resolves,
   so it has to be idempotent in both directions — each branch sets *and*
   clears, and none of them leaves a stale value behind on failure. */
function applySettings() {
  var s = SETTINGS;

  /* Reads "…cut, embroidered and shipped in 4–6 weeks", or just "…and shipped"
     when no lead time is published. */
  setSettingLine('step-lead-time', s.made_to_order_lead_time, ' in ');
  setSettingLine('footer-lead-time', s.made_to_order_lead_time, ' · ');
  setSettingLine('footer-size-note', sizeServiceNote());
  setSettingLine('footer-location', s.location);
  setSettingLine('pdp-size-note', sizeServiceNote());
  setSettingLine('inq-response-note', s.inquiry_response_note);

  var contacts = [
    setContactLink('contact-whatsapp', whatsappHref(s.whatsapp), 'WhatsApp'),
    setContactLink('contact-email', blank(s.contact_email) ? null : 'mailto:' + s.contact_email, s.contact_email),
    setContactLink('contact-instagram', externalHref(s.instagram_url), 'Instagram')
  ].filter(Boolean).length;

  /* A "Contact" heading with nothing under it reads as a broken page rather
     than an unfilled setting, so the column goes with its last link. */
  var col = byId('footer-contact');
  if (col) col.classList.toggle('hidden', contacts === 0);
}

/* Settings are not load-bearing: the catalogue is the storefront, and a
   settings outage must cost a few optional lines rather than the shop. So the
   failure path is blank settings, not an error state, and the promise always
   resolves. */
function loadSettings() {
  return fetch(SETTINGS_ENDPOINT, { headers: { Accept: 'application/json' } })
    .then(function (res) {
      if (!res.ok) throw new Error('HTTP ' + res.status);
      return res.json();
    })
    .then(function (payload) {
      var incoming = (payload && payload.settings) || {};
      var next = blankSettings();
      Object.keys(next).forEach(function (k) {
        next[k] = blank(incoming[k]) ? null : String(incoming[k]).trim();
      });
      SETTINGS = next;

      /* null until the app has merchandised the homepage — the endpoint says so
         explicitly rather than sending an object of defaults, so an untouched
         installation cannot accidentally look configured. */
      HOMEPAGE = (payload && payload.homepage) || null;
      CURATED_EDITS = (payload && Array.isArray(payload.curated_edits))
        ? payload.curated_edits : [];
      homepageState = 'ready';
    })
    .catch(function (err) {
      SETTINGS = blankSettings();
      /* An outage must not rearrange the homepage either — and the default
         hero is the established answer when the question cannot be asked, so
         the film loads now rather than never. */
      HOMEPAGE = null;
      CURATED_EDITS = [];
      homepageState = 'error';
      if (window.console && console.warn) console.warn('Site settings unavailable:', err);
    })
    .then(function () {
      applySettings();
      refreshViews();
    });
}

/* Re-render what is already on screen without re-running the route. The
   catalogue and the settings arrive independently and either can land after
   the visitor has started reading; routing again here would scroll them back
   to the top of the page mid-sentence. */
function refreshViews() {
  renderGrids();
  if (state.slug) renderProduct();
  renderBag();
}

/* Nobody should have to redeploy the site in January. */
function renderCopyrightYear() {
  var el = byId('copyright-year');
  if (el) el.textContent = String(new Date().getFullYear());
}

/* A candidate chosen from srcset that fails to load does NOT make the browser
   fall back to src — the element just goes broken. Every image here has a valid
   master in src, so one retry without srcset is the difference between a
   question mark and the photograph.
 *
 * Retried once and only once, and nothing is swallowed: if the master fails too
 * the image stays visibly broken, which is a real failure worth seeing. Error
 * events do not bubble, so this listens in the capture phase. */
document.addEventListener('error', function (e) {
  var img = e.target;
  if (!img || img.tagName !== 'IMG') return;
  if (!img.getAttribute('srcset') || img.dataset.srcsetRetried) return;

  /* Three ways an error can arrive for a load nobody is waiting for any more,
     and acting on any of them would damage whatever is on screen now.

     Detached: the element belonged to a grid that has since been rebuilt. */
  if (!img.isConnected) return;
  /* Already showing a photograph: the failure was for an earlier load that has
     since been superseded, and this element is fine. */
  if (img.complete && img.naturalWidth > 0) return;
  /* The shared PDP photograph, carrying a different product than the one this
     event was fired for. */
  if (img.dataset.render && img.dataset.render !== String(pdpRender)) return;

  img.dataset.srcsetRetried = '1';
  if (window.console && console.warn) {
    console.warn('Image candidate failed; falling back to the master:', img.currentSrc || img.src);
  }
  img.removeAttribute('srcset');
  img.removeAttribute('sizes');
  /* Reassigning src is what restarts the load now that the candidate list is
     gone; without it the element keeps its failed state. */
  var src = img.getAttribute('src');
  if (src) img.src = src;
}, true);

/* The Roselle film.
 *
 * It autoplays from the markup so it starts as early as possible; the only
 * thing needed here is to stop it for a visitor who has asked for less motion.
 * Pausing leaves the frame it reached on screen — or the poster, if it had not
 * started — which is a still image rather than a blank rectangle, and the
 * caption and its link keep working either way. No player is built.
 *
 * The preference is watched rather than read once, so turning it on in the OS
 * takes effect without a reload. */
function setupHeroFilm() {
  var video = byId('hero-video');
  if (!video) return;

  var query = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)');

  var apply = function () {
    if (query && query.matches) {
      video.autoplay = false;
      video.removeAttribute('autoplay');
      video.loop = false;
      if (!video.paused) video.pause();
    } else {
      video.loop = true;
      /* Autoplay can be refused — a data saver, a battery mode, a browser
         policy. Nothing is done about it on purpose: the poster stays, which
         is exactly the fallback wanted. */
      var attempt = video.play();
      if (attempt && attempt.catch) attempt.catch(function () {});
    }
  };

  apply();
  if (query) {
    if (query.addEventListener) query.addEventListener('change', apply);
    else if (query.addListener) query.addListener(apply);
  }

  /* A tap on the film plays or pauses it where it stands. The film is no longer
     inside a link, so this is the only thing a tap can do — it cannot route.
     Nothing here asks for fullscreen and nothing builds a player: the browser's
     own inline playback is left to do its job. */
  var startedAt = 0;
  video.addEventListener('play', function () { startedAt = Date.now(); });

  video.addEventListener('click', function () {
    if (video.paused) {
      var attempt = video.play();
      if (attempt && attempt.catch) attempt.catch(function () {});
      return;
    }
    /* When a phone refuses autoplay it draws its own play affordance, and the
       tap that dismisses it both starts playback and reaches this handler.
       Pausing then would undo the very tap that started the film, so a click
       arriving on the heels of playback is left alone. */
    if (Date.now() - startedAt > 400) video.pause();
  });
}

/* The Collections menus, desktop and compact.

   Hover opens the desktop one where a pointer can hover, but it is never the
   only way in: the control is a real button, it toggles on click and on Enter
   or Space for free, Escape closes it and returns focus, and tabbing out of it
   closes it behind you. */
function setupCollectionMenus() {
  var menus = [
    { btn: byId('collections-toggle'), panel: byId('collections-list'),
      wrap: byId('collections-menu'), hover: true },
    { btn: byId('mob-collections-toggle'), panel: byId('mob-collections-list'),
      wrap: null, hover: false }
  ].filter(function (m) { return m.btn && m.panel; });

  if (!menus.length) return;

  function setOpen(m, open) {
    m.panel.classList.toggle('hidden', !open);
    m.btn.setAttribute('aria-expanded', String(open));
  }
  function closeAll() {
    menus.forEach(function (m) { m.pinned = false; setOpen(m, false); });
  }
  function isOpen(m) { return m.btn.getAttribute('aria-expanded') === 'true'; }

  var canHover = !!(window.matchMedia && window.matchMedia('(hover:hover)').matches);

  menus.forEach(function (m) {
    setOpen(m, false);
    /* Hover opens the menu, but a click pins it: without that, hovering would
       open it and the click that followed would read as "already open" and
       shut it again — the control would feel broken to the one gesture most
       people reach for. Pinned, it stays put until it is dismissed. */
    m.pinned = false;

    m.btn.addEventListener('click', function (e) {
      e.stopPropagation();
      var next = !m.pinned;
      closeAll();
      m.pinned = next;
      setOpen(m, next);
    });

    if (m.hover && m.wrap && canHover) {
      m.wrap.addEventListener('mouseenter', function () { if (!m.pinned) setOpen(m, true); });
      m.wrap.addEventListener('mouseleave', function () { if (!m.pinned) setOpen(m, false); });
    }

    var region = m.wrap || m.panel;
    region.addEventListener('focusout', function (e) {
      var to = e.relatedTarget;
      if (to && (region.contains(to) || to === m.btn)) return;
      m.pinned = false;
      setOpen(m, false);
    });
  });

  document.addEventListener('keydown', function (e) {
    if (e.key !== 'Escape' && e.keyCode !== 27) return;
    var open = menus.filter(isOpen)[0];
    if (open) { closeAll(); open.btn.focus(); }
  });

  /* Anywhere else on the page closes it, and so does going somewhere. */
  document.addEventListener('click', function (e) {
    if (menus.some(function (m) { return m.btn.contains(e.target); })) return;
    closeAll();
  });
  window.addEventListener('hashchange', closeAll);
}

setupCollectionMenus();

/* Crossing the breakpoint moves the campaign button between the copy column and
   the image. Watched rather than read once, so rotating a phone is enough. */
(function () {
  if (!window.matchMedia) return;
  var q = window.matchMedia('(max-width:899px)');
  var again = function () { if (homepageBlock('campaign')) renderCampaign(); };
  if (q.addEventListener) q.addEventListener('change', again);
  else if (q.addListener) q.addListener(again);
})();

window.addEventListener('hashchange', route);
renderCopyrightYear();
applySettings();   /* blank until the fetch lands: hides every line it cannot fill */
loadBag();
loadCatalogue();
loadSettings();
